const TIMED_ARROWS_BANK = {"source":"content/timed/arrows/plexus_timed_bank_ai_reviewed.json","sha256":"3dd52c43620301431c86c541c08ebcc18ed28f7ded9973f56a102e114531e2c9","schema":"plexus-timed-bank-interchange-v1","review":{"status":"AI_REVIEWED_PASS","humanVerified":false,"reviewed":120,"pass":120},"counts":{"split":60,"sequence":30,"missingStep":30},"split":[{"contentId":"PLX-HYA-SPL-001","conceptId":"PLX-HYA-S001","systems":["Renal","Endocrine"],"topic":"Aldosterone and acid-base balance","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare sustained excess versus deficiency of aldosterone action, with respiratory compensation present.","labelA":"Aldosterone excess","labelB":"Aldosterone deficiency","tiles":[{"id":"t1","text":"Serum potassium falls","group":"a","why":"Greater distal potassium secretion can lower serum potassium."},{"id":"t2","text":"Serum bicarbonate rises","group":"a","why":"Greater distal hydrogen ion secretion promotes metabolic alkalosis."},{"id":"t3","text":"Compensatory PaCO2 rises","group":"a","why":"Hypoventilation partly compensates for the metabolic alkalosis."},{"id":"t4","text":"Serum potassium rises","group":"b","why":"Reduced distal potassium secretion favors hyperkalemia."},{"id":"t5","text":"Serum bicarbonate falls","group":"b","why":"Reduced acid excretion favors a normal anion gap metabolic acidosis."},{"id":"t6","text":"Compensatory PaCO2 falls","group":"b","why":"Increased ventilation partly compensates for the metabolic acidosis."}],"explanation":"Aldosterone promotes distal potassium and hydrogen ion secretion. Excess and deficiency therefore produce opposite potassium and acid-base patterns.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-002","conceptId":"PLX-HYA-S002","systems":["Pharmacology","Renal"],"topic":"ACE inhibition","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Expected directions after effective ACE inhibition, before clinically important escape or interacting therapies.","labelA":"Increases","labelB":"Decreases","tiles":[{"id":"t1","text":"Renin secretion","group":"a","why":"Loss of angiotensin II feedback and lower renal perfusion pressure stimulate renin."},{"id":"t2","text":"Angiotensin I concentration","group":"a","why":"More renin forms angiotensin I while its ACE-mediated conversion is inhibited."},{"id":"t3","text":"Efferent arteriolar diameter","group":"a","why":"Less angiotensin II action relaxes the renal efferent arteriole."},{"id":"t4","text":"Angiotensin II concentration","group":"b","why":"ACE inhibition reduces formation of angiotensin II."},{"id":"t5","text":"Aldosterone secretion","group":"b","why":"Less angiotensin II stimulation reduces aldosterone secretion."},{"id":"t6","text":"Systemic arteriolar resistance","group":"b","why":"Reduced angiotensin II vasoconstriction lowers systemic resistance."}],"explanation":"ACE inhibitors reduce angiotensin II and aldosterone while increasing renin and angiotensin I through feedback. Efferent arteriolar dilation is a key renal effect.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-003","conceptId":"PLX-HYA-S003","systems":["Endocrine"],"topic":"Primary versus secondary adrenal insufficiency","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare established adrenal cortical failure with isolated pituitary ACTH deficiency; exclude combined adrenal disease.","labelA":"Primary adrenal failure","labelB":"Pituitary ACTH deficiency","tiles":[{"id":"t1","text":"ACTH is elevated","group":"a","why":"Low cortisol removes feedback inhibition from an otherwise functioning pituitary."},{"id":"t2","text":"Aldosterone may be deficient","group":"a","why":"Adrenal cortical damage can impair both cortisol and aldosterone production."},{"id":"t3","text":"Hyperkalemia from mineralocorticoid loss","group":"a","why":"Low aldosterone reduces renal potassium secretion."},{"id":"t4","text":"ACTH is low or inappropriately normal","group":"b","why":"The pituitary signal is inadequate for the degree of hypocortisolism."},{"id":"t5","text":"Aldosterone is usually preserved","group":"b","why":"Renin-angiotensin signaling continues to regulate the zona glomerulosa."},{"id":"t6","text":"ACTH-driven pigmentation is absent","group":"b","why":"ACTH is not elevated enough to produce the characteristic pigmentation."}],"explanation":"The failing organ determines the pattern. Primary adrenal failure can remove mineralocorticoid activity, whereas isolated central ACTH deficiency generally spares it.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-004","conceptId":"PLX-HYA-S004","systems":["Endocrine","Renal"],"topic":"SIADH versus central diabetes insipidus","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classic untreated disease; central DI is complete and water intake cannot replace ongoing losses.","labelA":"SIADH","labelB":"Central diabetes insipidus","tiles":[{"id":"t1","text":"Dilutional hyponatremia","group":"a","why":"Water retention lowers serum sodium in SIADH."},{"id":"t2","text":"Inappropriately concentrated urine","group":"a","why":"ADH action persists despite low plasma tonicity."},{"id":"t3","text":"Ectopic ADH from small cell lung cancer","group":"a","why":"Some small cell lung cancers produce ADH inappropriately."},{"id":"t4","text":"Hypernatremia from free-water loss","group":"b","why":"Unreplaced urinary water losses raise serum sodium."},{"id":"t5","text":"Very dilute urine despite hypertonicity","group":"b","why":"ADH deficiency prevents an appropriate concentrating response."},{"id":"t6","text":"Urine concentrates with desmopressin","group":"b","why":"Replacement of the missing hormone restores renal water reabsorption."}],"explanation":"SIADH retains water despite low tonicity. Central DI loses water because ADH secretion is deficient.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-005","conceptId":"PLX-HYA-S005","systems":["Endocrine","Renal"],"topic":"Central versus nephrogenic diabetes insipidus","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare complete central DI with complete nephrogenic DI; partial disease can produce overlapping test responses.","labelA":"Central DI","labelB":"Nephrogenic DI","tiles":[{"id":"t1","text":"Deficient ADH secretion","group":"a","why":"The hypothalamic-pituitary system fails to provide adequate hormone."},{"id":"t2","text":"Hypothalamic-pituitary injury","group":"a","why":"Trauma can damage ADH production or release."},{"id":"t3","text":"Strong desmopressin response","group":"a","why":"The kidney can respond when the missing hormone is supplied."},{"id":"t4","text":"Renal resistance to ADH","group":"b","why":"The collecting duct does not respond normally to the hormone."},{"id":"t5","text":"Lithium-associated concentrating defect","group":"b","why":"Lithium can impair collecting duct responsiveness to ADH."},{"id":"t6","text":"Minimal desmopressin response","group":"b","why":"Adding hormone does little when the kidney remains resistant."}],"explanation":"Central DI is a hormone-deficiency problem. Nephrogenic DI is a renal-response problem.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-006","conceptId":"PLX-HYA-S006","systems":["Endocrine","Renal"],"topic":"SIADH versus primary polydipsia","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Both patients have hypotonic hyponatremia. Compare isolated SIADH with excess water intake and intact renal dilution.","labelA":"SIADH","labelB":"Primary polydipsia","tiles":[{"id":"t1","text":"ADH activity remains inappropriate","group":"a","why":"ADH is not adequately suppressed by low plasma tonicity."},{"id":"t2","text":"Urine remains concentrated","group":"a","why":"Continued collecting duct water reabsorption limits free-water excretion."},{"id":"t3","text":"Ectopic ADH is a possible cause","group":"a","why":"Small cell lung cancer can provide an autonomous ADH source."},{"id":"t4","text":"ADH is appropriately suppressed","group":"b","why":"Low plasma tonicity normally switches off ADH release."},{"id":"t5","text":"Urine is maximally dilute","group":"b","why":"Suppressed ADH permits excretion of dilute urine."},{"id":"t6","text":"Water intake overwhelms excretion","group":"b","why":"A very large water load can exceed excretory capacity."}],"explanation":"Urine concentration distinguishes these classic causes of hypotonic hyponatremia. Low sodium alone does not establish SIADH.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-007","conceptId":"PLX-HYA-S007","systems":["Endocrine"],"topic":"Primary hyperthyroidism versus hypothyroidism","tier":0,"prompt":"Sort all six tiles into the two groups.","context":"Overt untreated primary thyroid disease; assess free thyroid hormones rather than isolated binding-protein effects.","labelA":"Primary hyperthyroidism","labelB":"Primary hypothyroidism","tiles":[{"id":"t1","text":"TSH is suppressed","group":"a","why":"Excess thyroid hormone suppresses pituitary TSH through negative feedback."},{"id":"t2","text":"Free T4 is elevated","group":"a","why":"The primary thyroid abnormality produces excess circulating hormone."},{"id":"t3","text":"T3 is typically elevated","group":"a","why":"Overt primary hyperthyroidism usually raises circulating T3."},{"id":"t4","text":"TSH is elevated","group":"b","why":"The pituitary responds to deficient thyroid hormone by releasing more TSH."},{"id":"t5","text":"Free T4 is reduced","group":"b","why":"The thyroid gland cannot supply adequate T4."},{"id":"t6","text":"Thyroid hormone feedback is reduced","group":"b","why":"Less hormone feedback allows pituitary TSH secretion to rise."}],"explanation":"In primary thyroid disease, TSH generally moves opposite to free T4. This differs from central thyroid disease.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-008","conceptId":"PLX-HYA-S008","systems":["Endocrine"],"topic":"Graves disease versus destructive thyroiditis","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare untreated Graves disease with the thyrotoxic phase of destructive thyroiditis; exclude recent iodine exposure.","labelA":"Graves disease","labelB":"Destructive thyroiditis","tiles":[{"id":"t1","text":"TSH-receptor stimulating antibodies","group":"a","why":"Autoantibodies stimulate thyroid hormone synthesis in Graves disease."},{"id":"t2","text":"Diffuse increased radioiodine uptake","group":"a","why":"An actively synthesizing gland takes up more iodine diffusely."},{"id":"t3","text":"Increased new hormone synthesis","group":"a","why":"Receptor stimulation drives synthesis rather than simple leakage."},{"id":"t4","text":"Release of stored thyroid hormone","group":"b","why":"Follicular injury releases preformed hormone."},{"id":"t5","text":"Low radioiodine uptake","group":"b","why":"Thyrotoxicosis occurs without increased hormone synthesis."},{"id":"t6","text":"Painful postviral thyroid inflammation","group":"b","why":"Subacute granulomatous thyroiditis is a painful destructive thyroiditis."}],"explanation":"Both can suppress TSH and raise thyroid hormone levels. Uptake separates stimulated synthesis from destructive hormone release.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-009","conceptId":"PLX-HYA-S009","systems":["Endocrine"],"topic":"Primary versus central hypothyroidism","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare overt primary hypothyroidism with pituitary central hypothyroidism; exclude nonthyroidal illness and assay interference.","labelA":"Primary hypothyroidism","labelB":"Central hypothyroidism","tiles":[{"id":"t1","text":"High TSH with low free T4","group":"a","why":"An intact pituitary increases its signal to a failing thyroid gland."},{"id":"t2","text":"Hashimoto thyroid destruction","group":"a","why":"Autoimmune injury occurs in the thyroid itself."},{"id":"t3","text":"Thyroid gland is the primary defect","group":"a","why":"The hormone-producing target gland is failing."},{"id":"t4","text":"Low free T4 without an adequate TSH rise","group":"b","why":"Pituitary TSH secretion is insufficient for the hormone deficit."},{"id":"t5","text":"Sheehan-related pituitary injury","group":"b","why":"Postpartum pituitary ischemia can impair TSH secretion."},{"id":"t6","text":"Pituitary stimulation is inadequate","group":"b","why":"The thyroid receives an insufficient central signal."}],"explanation":"A low free T4 requires an appropriately increased TSH response. Failure of that response suggests central disease.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-010","conceptId":"PLX-HYA-S010","systems":["Microbiology","Neurology"],"topic":"Bacterial versus viral meningitis CSF","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classic uncomplicated CSF patterns after the very early phase; these are typical patterns, not diagnostic rules.","labelA":"Typical bacterial meningitis","labelB":"Typical viral meningitis","tiles":[{"id":"t1","text":"Predominantly neutrophilic pleocytosis","group":"a","why":"Pyogenic bacterial meningitis classically recruits neutrophils."},{"id":"t2","text":"Reduced CSF glucose","group":"a","why":"Bacterial meningitis commonly lowers CSF glucose relative to blood."},{"id":"t3","text":"Often markedly elevated CSF protein","group":"a","why":"Blood-CSF barrier inflammation can cause a large protein increase."},{"id":"t4","text":"Predominantly lymphocytic pleocytosis","group":"b","why":"Most established viral meningitis has a lymphocytic CSF response."},{"id":"t5","text":"Usually preserved CSF glucose","group":"b","why":"Glucose is usually normal in uncomplicated viral meningitis."},{"id":"t6","text":"Usually modest CSF protein elevation","group":"b","why":"Protein is often mildly elevated rather than markedly increased."}],"explanation":"Cell differential, glucose and protein are interpreted together. Early viral disease, treated bacterial disease and specific pathogens may depart from these patterns.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-011","conceptId":"PLX-HYA-S011","systems":["Endocrine"],"topic":"Thyroid-binding globulin changes","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"An otherwise euthyroid person has an isolated TBG change and has reached a new steady state.","labelA":"Increased TBG","labelB":"Decreased TBG","tiles":[{"id":"t1","text":"Total T4 rises","group":"a","why":"More hormone is carried in the enlarged bound pool."},{"id":"t2","text":"Free-to-total T4 fraction falls","group":"a","why":"Free T4 normalizes while total T4 remains higher."},{"id":"t3","text":"Estrogen-associated binding increase","group":"a","why":"Estrogen increases circulating TBG."},{"id":"t4","text":"Total T4 falls","group":"b","why":"The reduced bound pool lowers total measured hormone."},{"id":"t5","text":"Free-to-total T4 fraction rises","group":"b","why":"Free T4 remains normal despite lower total T4."},{"id":"t6","text":"Inherited TBG deficiency","group":"b","why":"Reduced carrier abundance changes total hormone without obligate hypothyroidism."}],"explanation":"Binding-protein changes affect total hormone more than steady-state free hormone. A low total T4 alone does not prove hypothyroidism.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-012","conceptId":"PLX-HYA-S012","systems":["Endocrine"],"topic":"Conditions that raise or suppress TSH","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Untreated classic biochemical patterns; classify by the expected TSH direction.","labelA":"TSH elevated","labelB":"TSH suppressed","tiles":[{"id":"t1","text":"Overt primary hypothyroidism","group":"a","why":"Deficient thyroid hormone removes negative feedback on the pituitary."},{"id":"t2","text":"Subclinical primary hypothyroidism","group":"a","why":"TSH rises while free T4 remains in range."},{"id":"t3","text":"TSH-secreting pituitary adenoma","group":"a","why":"Autonomous pituitary secretion produces inappropriately elevated TSH."},{"id":"t4","text":"Untreated Graves disease","group":"b","why":"High thyroid hormone suppresses pituitary TSH despite antibody-driven gland stimulation."},{"id":"t5","text":"Thyrotoxic destructive thyroiditis","group":"b","why":"Released stored hormone suppresses pituitary TSH."},{"id":"t6","text":"Excess exogenous T3","group":"b","why":"Exogenous hormone exerts negative feedback on pituitary TSH."}],"explanation":"TSH reflects both feedback and the location of disease. TSH-secreting adenomas are an important exception to suppression during thyrotoxicosis.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-013","conceptId":"PLX-HYA-S013","systems":["Endocrine"],"topic":"Primary parathyroid excess versus deficiency","tier":0,"prompt":"Sort all six tiles into the two groups.","context":"Untreated primary parathyroid disease, with preserved renal function.","labelA":"Primary hyperparathyroidism","labelB":"Primary hypoparathyroidism","tiles":[{"id":"t1","text":"Serum calcium is high","group":"a","why":"Excess PTH increases calcium mobilization and retention."},{"id":"t2","text":"Serum phosphate is low","group":"a","why":"PTH increases renal phosphate excretion."},{"id":"t3","text":"PTH is high or inappropriately normal","group":"a","why":"PTH fails to suppress despite hypercalcemia."},{"id":"t4","text":"Serum calcium is low","group":"b","why":"Insufficient PTH reduces support for calcium homeostasis."},{"id":"t5","text":"Serum phosphate is high","group":"b","why":"Reduced PTH permits greater renal phosphate retention."},{"id":"t6","text":"PTH is low or inappropriately normal","group":"b","why":"PTH fails to rise appropriately despite hypocalcemia."}],"explanation":"Interpret PTH relative to calcium. A numerically normal PTH can still be inappropriate for the calcium concentration.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-014","conceptId":"PLX-HYA-S014","systems":["Endocrine","Renal"],"topic":"Direct and indirect PTH effects","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Sustained PTH activity in a person with functioning kidneys and stable dietary calcium intake.","labelA":"Increases","labelB":"Decreases","tiles":[{"id":"t1","text":"Distal calcium reabsorption","group":"a","why":"PTH increases calcium reabsorption in the distal nephron."},{"id":"t2","text":"Renal 1-alpha-hydroxylase activity","group":"a","why":"PTH promotes renal conversion of calcidiol to calcitriol."},{"id":"t3","text":"Osteoblast-lineage RANKL expression","group":"a","why":"PTH signaling supports osteoclast activation indirectly through RANKL."},{"id":"t4","text":"Proximal phosphate reabsorption","group":"b","why":"PTH reduces proximal phosphate transporter abundance."},{"id":"t5","text":"Serum phosphate","group":"b","why":"Greater phosphaturia tends to lower circulating phosphate."},{"id":"t6","text":"Fecal calcium loss","group":"b","why":"Calcitriol-mediated intestinal calcium absorption reduces the unabsorbed fraction."}],"explanation":"PTH conserves calcium, promotes phosphaturia and increases calcitriol formation. Sustained skeletal effects involve osteoblast-lineage signaling to osteoclasts.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-015","conceptId":"PLX-HYA-S015","systems":["Endocrine"],"topic":"Low PTH versus PTH resistance","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Both patients have hypocalcemia and hyperphosphatemia; compare gland failure with classic PTH resistance.","labelA":"Primary hypoparathyroidism","labelB":"Pseudohypoparathyroidism","tiles":[{"id":"t1","text":"PTH is deficient","group":"a","why":"The parathyroid glands provide an inadequate hormone signal."},{"id":"t2","text":"Parathyroid injury after thyroidectomy","group":"a","why":"Surgical damage can reduce PTH secretion."},{"id":"t3","text":"DiGeorge-related parathyroid hypoplasia","group":"a","why":"Poor parathyroid development can produce primary gland deficiency."},{"id":"t4","text":"PTH is elevated despite hypocalcemia","group":"b","why":"The glands compensate for deficient target-organ response."},{"id":"t5","text":"Albright hereditary osteodystrophy phenotype","group":"b","why":"Some forms include short metacarpals and ectopic ossification."},{"id":"t6","text":"Blunted urinary cAMP response to PTH","group":"b","why":"Classic type I disease has impaired PTH-stimulated cAMP signaling."}],"explanation":"Both conditions can look like low PTH action. The circulating PTH concentration and classic signaling response distinguish them.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-016","conceptId":"PLX-HYA-S016","systems":["Renal","Endocrine"],"topic":"Renal versus nutritional secondary hyperparathyroidism","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare advanced untreated CKD with isolated nutritional vitamin D deficiency and normal kidney function.","labelA":"Advanced CKD pattern","labelB":"Nutritional vitamin D deficiency","tiles":[{"id":"t1","text":"Renal phosphate clearance is impaired","group":"a","why":"Reduced kidney clearance favors phosphate accumulation."},{"id":"t2","text":"Renal activation tissue is lost","group":"a","why":"Loss of functioning nephrons impairs calcitriol activation."},{"id":"t3","text":"Low calcium with high phosphate","group":"a","why":"Advanced CKD can cause this classic secondary hyperparathyroid pattern."},{"id":"t4","text":"Dietary vitamin D supply is inadequate","group":"b","why":"Insufficient vitamin D intake reduces the available substrate."},{"id":"t5","text":"Renal activation tissue is intact","group":"b","why":"The isolated nutritional disorder does not destroy functioning nephrons."},{"id":"t6","text":"Low calcium with low phosphate","group":"b","why":"Reduced absorption and secondary phosphaturia produce this classic pattern."}],"explanation":"Both disorders can raise PTH. Preserved versus impaired renal phosphate clearance helps separate their classic patterns.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-017","conceptId":"PLX-HYA-S017","systems":["Endocrine","Renal"],"topic":"Primary hyperparathyroidism versus FHH","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare classic untreated patterns; exclude lithium, thiazides, vitamin D deficiency and impaired renal function.","labelA":"Primary hyperparathyroidism","labelB":"Familial hypocalciuric hypercalcemia","tiles":[{"id":"t1","text":"Parathyroid adenoma","group":"a","why":"An autonomously functioning gland is a common cause."},{"id":"t2","text":"Urinary calcium often higher","group":"a","why":"Many patients excrete more calcium than those with FHH."},{"id":"t3","text":"Symptomatic calcium stones may occur","group":"a","why":"Hypercalciuria can contribute to nephrolithiasis."},{"id":"t4","text":"Reduced calcium-sensing receptor function","group":"b","why":"A higher calcium set point affects parathyroid and renal calcium handling."},{"id":"t5","text":"Low urinary calcium is characteristic","group":"b","why":"The kidney retains calcium despite the elevated serum concentration."},{"id":"t6","text":"Often lifelong mild familial hypercalcemia","group":"b","why":"A benign inherited pattern supports FHH."}],"explanation":"Both may have hypercalcemia with nonsuppressed PTH. Urinary calcium and the clinical context help distinguish FHH from primary hyperparathyroidism.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-018","conceptId":"PLX-HYA-S018","systems":["Endocrine","Oncology"],"topic":"PTH-dependent versus independent hypercalcemia","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classify the expected endogenous PTH response during each named cause of hypercalcemia.","labelA":"PTH not appropriately suppressed","labelB":"PTH suppressed","tiles":[{"id":"t1","text":"Parathyroid adenoma","group":"a","why":"Autonomous PTH secretion drives the calcium elevation."},{"id":"t2","text":"Tertiary hyperparathyroidism","group":"a","why":"Long-standing gland hyperplasia becomes autonomous."},{"id":"t3","text":"Familial hypocalciuric hypercalcemia","group":"a","why":"The altered calcium set point permits nonsuppressed PTH."},{"id":"t4","text":"PTHrP-secreting malignancy","group":"b","why":"Tumor PTHrP raises calcium while endogenous PTH is inhibited."},{"id":"t5","text":"Calcitriol-mediated sarcoid hypercalcemia","group":"b","why":"Excess extrarenal calcitriol raises calcium independently of PTH."},{"id":"t6","text":"Osteolytic malignant hypercalcemia","group":"b","why":"Bone destruction raises calcium and suppresses endogenous PTH."}],"explanation":"PTH should be suppressed by hypercalcemia. Failure to suppress suggests a PTH-dependent mechanism or an altered calcium-sensing set point.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-019","conceptId":"PLX-HYA-S019","systems":["Musculoskeletal","Endocrine"],"topic":"Osteoporosis versus osteomalacia","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare uncomplicated osteoporosis with vitamin D deficiency causing osteomalacia.","labelA":"Osteoporosis","labelB":"Osteomalacia","tiles":[{"id":"t1","text":"Reduced amount of bone","group":"a","why":"Bone mass is reduced without a primary mineralization defect."},{"id":"t2","text":"Remaining matrix is mineralized normally","group":"a","why":"The primary problem is bone quantity."},{"id":"t3","text":"Routine mineral labs often normal","group":"a","why":"Uncomplicated osteoporosis usually preserves serum calcium, phosphate and PTH."},{"id":"t4","text":"Defective osteoid mineralization","group":"b","why":"New matrix does not acquire adequate mineral."},{"id":"t5","text":"Excess unmineralized osteoid","group":"b","why":"Poor mineralization leaves osteoid relatively abundant."},{"id":"t6","text":"Vitamin D deficiency is a classic cause","group":"b","why":"Inadequate vitamin D impairs calcium and phosphate availability."}],"explanation":"Osteoporosis reduces bone quantity. Osteomalacia impairs the mineralization of bone matrix.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-020","conceptId":"PLX-HYA-S020","systems":["Musculoskeletal","Endocrine"],"topic":"Paget disease versus primary hyperparathyroidism","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare classic active Paget disease with uncomplicated primary hyperparathyroidism.","labelA":"Paget disease of bone","labelB":"Primary hyperparathyroidism","tiles":[{"id":"t1","text":"Isolated bone ALP elevation","group":"a","why":"Increased bone turnover often raises ALP while mineral labs remain normal."},{"id":"t2","text":"Mixed lytic and sclerotic bone changes","group":"a","why":"Disorganized high turnover produces mixed remodeling patterns."},{"id":"t3","text":"Progressive skull enlargement","group":"a","why":"Remodeled skull bone can increase head size."},{"id":"t4","text":"Hypercalcemia with low phosphate","group":"b","why":"PTH raises calcium and promotes renal phosphate loss."},{"id":"t5","text":"PTH is inappropriately nonsuppressed","group":"b","why":"PTH secretion persists despite elevated serum calcium."},{"id":"t6","text":"Parathyroid adenoma is common","group":"b","why":"A single hyperfunctioning gland is a frequent cause."}],"explanation":"An ALP rise can occur in both disorders, but isolated ALP elevation with normal calcium favors classic Paget disease.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-021","conceptId":"PLX-HYA-S021","systems":["Endocrine","Renal"],"topic":"Sarcoid versus renal calcitriol physiology","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare calcitriol-mediated sarcoid hypercalcemia with advanced untreated CKD causing secondary hyperparathyroidism.","labelA":"Sarcoid hypercalcemia","labelB":"Advanced CKD","tiles":[{"id":"t1","text":"Extrarenal macrophage 1-alpha-hydroxylase","group":"a","why":"Granuloma macrophages generate calcitriol outside the kidney."},{"id":"t2","text":"Calcitriol is inappropriately elevated","group":"a","why":"Extrarenal activation can continue despite normal suppressive signals."},{"id":"t3","text":"Endogenous PTH is suppressed","group":"a","why":"The associated hypercalcemia inhibits parathyroid secretion."},{"id":"t4","text":"Nephron loss reduces activation capacity","group":"b","why":"Loss of functioning renal tissue reduces vitamin D activation capacity."},{"id":"t5","text":"Intestinal calcium absorption is reduced","group":"b","why":"Low calcitriol provides less support for calcium absorption."},{"id":"t6","text":"Secondary PTH secretion increases","group":"b","why":"Calcium, phosphate and vitamin D abnormalities stimulate the parathyroids."}],"explanation":"Macrophage calcitriol production and failed renal calcitriol production have opposite effects on calcium-PTH feedback.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-022","conceptId":"PLX-HYA-S022","systems":["Reproductive","Endocrine"],"topic":"LH versus FSH targets","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Sort normal gonadotropin actions in the gonads.","labelA":"LH action","labelB":"FSH action","tiles":[{"id":"t1","text":"Leydig cell testosterone synthesis","group":"a","why":"LH stimulates Leydig cells in the testes."},{"id":"t2","text":"Theca cell androgen synthesis","group":"a","why":"LH stimulates androgen production in ovarian theca cells."},{"id":"t3","text":"Ovulatory surge trigger","group":"a","why":"The LH surge triggers ovulation."},{"id":"t4","text":"Sertoli cell inhibin B secretion","group":"b","why":"FSH stimulates Sertoli cell function and inhibin B output."},{"id":"t5","text":"Granulosa cell aromatase activity","group":"b","why":"FSH promotes ovarian conversion of androgens to estrogens."},{"id":"t6","text":"Ovarian follicular growth","group":"b","why":"FSH supports development of ovarian follicles."}],"explanation":"LH supports androgen-producing cells and ovulation. FSH supports granulosa or Sertoli cell functions.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-023","conceptId":"PLX-HYA-S023","systems":["Reproductive","Endocrine"],"topic":"Ovarian failure versus hypothalamic amenorrhea","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare established primary ovarian insufficiency with functional hypothalamic amenorrhea from low energy availability.","labelA":"Primary ovarian insufficiency","labelB":"Hypothalamic amenorrhea","tiles":[{"id":"t1","text":"FSH is persistently elevated","group":"a","why":"Loss of ovarian feedback permits a strong pituitary FSH response."},{"id":"t2","text":"LH tends to be elevated","group":"a","why":"Loss of sex-steroid feedback increases gonadotropin drive."},{"id":"t3","text":"Turner-related streak ovaries","group":"a","why":"Primary ovarian dysfunction can follow gonadal dysgenesis."},{"id":"t4","text":"GnRH pulsatility is reduced","group":"b","why":"Low energy availability suppresses hypothalamic reproductive signaling."},{"id":"t5","text":"Gonadotropins are low or inadequate","group":"b","why":"The central signal fails to rise appropriately despite low estrogen."},{"id":"t6","text":"Energy deficit is the central trigger","group":"b","why":"Restricted intake or heavy exercise can suppress the hypothalamic axis."}],"explanation":"Low estrogen appears in both. The gonadotropin response identifies whether the main problem is ovarian or central.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-024","conceptId":"PLX-HYA-S024","systems":["Reproductive","Genetics"],"topic":"Turner versus Klinefelter syndrome","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classic chromosomal and gonadal findings; mosaic presentations may differ.","labelA":"Turner syndrome","labelB":"Klinefelter syndrome","tiles":[{"id":"t1","text":"45,X karyotype","group":"a","why":"Loss of one sex chromosome produces the classic Turner karyotype."},{"id":"t2","text":"Streak ovaries","group":"a","why":"Gonadal dysgenesis produces primary ovarian failure."},{"id":"t3","text":"Aortic coarctation association","group":"a","why":"Coarctation is a recognized cardiovascular association."},{"id":"t4","text":"47,XXY karyotype","group":"b","why":"An additional X chromosome produces the classic Klinefelter karyotype."},{"id":"t5","text":"Seminiferous tubule dysfunction","group":"b","why":"Testicular dysfunction impairs reproductive function."},{"id":"t6","text":"Primary testicular hypogonadism","group":"b","why":"Primary testicular failure reduces testosterone feedback and raises gonadotropins."}],"explanation":"Both can cause hypergonadotropic hypogonadism, but their karyotypes, gonadal anatomy and associated findings differ.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-025","conceptId":"PLX-HYA-S025","systems":["Reproductive","Endocrine"],"topic":"Androgen receptor versus DHT synthesis defect","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare complete androgen insensitivity with classic 5-alpha-reductase deficiency in a person with a 46,XY karyotype.","labelA":"Complete androgen insensitivity","labelB":"5-alpha-reductase deficiency","tiles":[{"id":"t1","text":"Androgen receptor does not function","group":"a","why":"Target tissues cannot respond normally to testosterone or DHT."},{"id":"t2","text":"Scant pubic and axillary hair","group":"a","why":"Hair growth dependent on androgen signaling is reduced."},{"id":"t3","text":"No typical androgen-driven virilization","group":"a","why":"Complete receptor failure prevents the usual androgen response."},{"id":"t4","text":"DHT synthesis is impaired","group":"b","why":"Conversion of testosterone to dihydrotestosterone is reduced."},{"id":"t5","text":"Testosterone-to-DHT ratio is high","group":"b","why":"Testosterone is relatively preserved compared with its DHT product."},{"id":"t6","text":"Pubertal virilization can occur","group":"b","why":"Rising testosterone can act through intact androgen receptors at puberty."}],"explanation":"The receptor defect blocks androgen action. The enzyme defect mainly impairs DHT formation while preserving testosterone receptor signaling.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-026","conceptId":"PLX-HYA-S026","systems":["Endocrine","Pharmacology"],"topic":"Regulation of prolactin secretion","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classify the usual effect on prolactin secretion; exclude mixed pituitary disease.","labelA":"Prolactin increases","labelB":"Prolactin decreases","tiles":[{"id":"t1","text":"Prolactinoma","group":"a","why":"A prolactin-secreting adenoma increases circulating hormone."},{"id":"t2","text":"D2 receptor antagonism","group":"a","why":"Blocking dopamine removes tonic inhibition of lactotrophs."},{"id":"t3","text":"Pituitary stalk interruption","group":"a","why":"Loss of hypothalamic dopamine delivery can disinhibit prolactin secretion."},{"id":"t4","text":"Hypothalamic dopamine action","group":"b","why":"Dopamine normally inhibits lactotroph secretion through D2 receptors."},{"id":"t5","text":"Bromocriptine therapy","group":"b","why":"D2 agonism suppresses prolactin secretion."},{"id":"t6","text":"Extensive postpartum pituitary necrosis","group":"b","why":"Destruction of lactotrophs can cause low prolactin and failure of lactation."}],"explanation":"Prolactin is under tonic dopamine inhibition. Interruption of that inhibition raises prolactin, whereas destruction of the secreting cells lowers it.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-027","conceptId":"PLX-HYA-S027","systems":["Endocrine"],"topic":"21- versus 11-beta-hydroxylase deficiency","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare classic salt-wasting 21-hydroxylase deficiency with classic 11-beta-hydroxylase deficiency.","labelA":"Salt-wasting 21-hydroxylase defect","labelB":"11-beta-hydroxylase defect","tiles":[{"id":"t1","text":"Volume depletion and hypotension","group":"a","why":"Low aldosterone action causes renal salt loss."},{"id":"t2","text":"Hyperkalemia","group":"a","why":"Mineralocorticoid deficiency limits renal potassium secretion."},{"id":"t3","text":"Deficient deoxycorticosterone synthesis","group":"a","why":"21-hydroxylase is required to form the mineralocorticoid precursor DOC."},{"id":"t4","text":"Mineralocorticoid hypertension","group":"b","why":"DOC accumulates and provides mineralocorticoid activity."},{"id":"t5","text":"Potassium tends to be low","group":"b","why":"Mineralocorticoid activity promotes renal potassium secretion."},{"id":"t6","text":"Deoxycorticosterone accumulates","group":"b","why":"The blocked conversion downstream of DOC allows it to build up."}],"explanation":"Both defects can cause androgen excess. DOC-mediated mineralocorticoid activity separates the classic 11-beta defect from salt-wasting 21-hydroxylase deficiency.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-028","conceptId":"PLX-HYA-S028","systems":["Endocrine"],"topic":"11-beta- versus 17-alpha-hydroxylase deficiency","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Both can cause DOC-mediated mineralocorticoid hypertension. Sort their contrasting androgen-precursor patterns.","labelA":"11-beta-hydroxylase deficiency","labelB":"17-alpha-hydroxylase deficiency","tiles":[{"id":"t1","text":"Adrenal androgen excess","group":"a","why":"Steroid precursors are shunted toward androgen synthesis."},{"id":"t2","text":"DHEA-S is elevated","group":"a","why":"Androgen production remains available and is increased by ACTH drive."},{"id":"t3","text":"17-hydroxy precursors accumulate","group":"a","why":"Upstream 17-hydroxylated substrates can build up."},{"id":"t4","text":"Adrenal androgen deficiency","group":"b","why":"The pathway cannot efficiently form 17-hydroxylated androgen precursors."},{"id":"t5","text":"DHEA-S is reduced","group":"b","why":"Androgen synthesis is impaired."},{"id":"t6","text":"17-hydroxy precursors are reduced","group":"b","why":"The deficient enzyme cannot perform the required 17-hydroxylation."}],"explanation":"Androgen excess favors the 11-beta defect. Androgen deficiency favors the 17-alpha defect when both present with mineralocorticoid hypertension.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-029","conceptId":"PLX-HYA-S029","systems":["Renal","Gastrointestinal"],"topic":"Vomiting versus diarrhea acid-base effects","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare substantial gastric acid loss with bicarbonate-rich diarrheal loss; exclude mixed disorders.","labelA":"Vomiting","labelB":"Diarrhea","tiles":[{"id":"t1","text":"Metabolic alkalosis","group":"a","why":"Loss of gastric hydrogen ions raises plasma bicarbonate relative to acid."},{"id":"t2","text":"Hydrochloric acid loss","group":"a","why":"Gastric fluid contains hydrogen and chloride ions."},{"id":"t3","text":"Compensatory PaCO2 rises","group":"a","why":"Reduced ventilation partly offsets the alkalosis."},{"id":"t4","text":"Normal anion gap metabolic acidosis","group":"b","why":"Loss of bicarbonate lowers plasma buffering capacity."},{"id":"t5","text":"Stool bicarbonate loss","group":"b","why":"Bicarbonate-rich intestinal fluid is lost from the body."},{"id":"t6","text":"Compensatory PaCO2 falls","group":"b","why":"Increased ventilation partly offsets the acidosis."}],"explanation":"The composition of the lost fluid determines the primary disorder. Both conditions can deplete potassium.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-030","conceptId":"PLX-HYA-S030","systems":["Renal","Acid-base"],"topic":"High versus normal anion gap acidosis","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classify the classic primary metabolic acidosis before treatment or additional mixed disorders.","labelA":"High anion gap","labelB":"Normal anion gap","tiles":[{"id":"t1","text":"Diabetic ketoacidosis","group":"a","why":"Accumulated ketoanions increase the anion gap."},{"id":"t2","text":"Lactic acidosis","group":"a","why":"Accumulated lactate increases the anion gap."},{"id":"t3","text":"Methanol toxicity","group":"a","why":"Toxic organic acid metabolites can raise the gap."},{"id":"t4","text":"Bicarbonate-losing diarrhea","group":"b","why":"Bicarbonate loss is offset largely by a relative chloride rise."},{"id":"t5","text":"Proximal renal tubular acidosis","group":"b","why":"Impaired proximal bicarbonate reclamation causes a hyperchloremic acidosis."},{"id":"t6","text":"Hypoaldosteronism-related type 4 RTA","group":"b","why":"Reduced distal acid excretion causes a typically hyperchloremic acidosis."}],"explanation":"Accumulated unmeasured anions raise the gap. Bicarbonate loss or selected renal acidification defects can cause a normal-gap acidosis.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-031","conceptId":"PLX-HYA-S031","systems":["Pharmacology","Renal"],"topic":"Loop versus thiazide diuretics","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare the main nephron target and urinary calcium effect of each diuretic class.","labelA":"Loop diuretic","labelB":"Thiazide diuretic","tiles":[{"id":"t1","text":"NKCC2 inhibition","group":"a","why":"Loop diuretics inhibit the sodium-potassium-2 chloride cotransporter."},{"id":"t2","text":"Thick ascending limb target","group":"a","why":"The main site of action is the thick ascending loop of Henle."},{"id":"t3","text":"Urinary calcium excretion rises","group":"a","why":"Loss of the lumen-positive gradient reduces calcium reabsorption."},{"id":"t4","text":"NCC inhibition","group":"b","why":"Thiazides inhibit the sodium-chloride cotransporter."},{"id":"t5","text":"Early distal convoluted tubule target","group":"b","why":"The main site of action is the early distal convoluted tubule."},{"id":"t6","text":"Urinary calcium excretion falls","group":"b","why":"Thiazides increase net renal calcium reabsorption."}],"explanation":"Loops and thiazides can both waste potassium and promote alkalosis. Their transporter targets and calcium effects differ.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-032","conceptId":"PLX-HYA-S032","systems":["Pharmacology","Renal"],"topic":"Drug effects on potassium","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classify a recognized potassium effect of the drug used alone; actual concentrations depend on dose and kidney function.","labelA":"Can promote hyperkalemia","labelB":"Can promote hypokalemia","tiles":[{"id":"t1","text":"Spironolactone","group":"a","why":"Mineralocorticoid receptor blockade reduces distal potassium secretion."},{"id":"t2","text":"Amiloride","group":"a","why":"ENaC blockade reduces the electrical drive for potassium secretion."},{"id":"t3","text":"Lisinopril","group":"a","why":"Lower aldosterone activity reduces renal potassium excretion."},{"id":"t4","text":"Furosemide","group":"b","why":"Greater distal sodium delivery and volume-mediated aldosterone activity promote potassium loss."},{"id":"t5","text":"Hydrochlorothiazide","group":"b","why":"Distal sodium delivery and aldosterone action promote potassium loss."},{"id":"t6","text":"Acetazolamide","group":"b","why":"Bicarbonaturia and greater distal sodium delivery can promote potassium wasting."}],"explanation":"Potassium-sparing mechanisms reduce distal potassium secretion. Several other diuretics increase urinary potassium loss.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-033","conceptId":"PLX-HYA-S033","systems":["Pharmacology","Renal"],"topic":"Acetazolamide urine versus serum changes","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Early bicarbonaturic effect of acetazolamide, with functioning kidneys and no mixed acid-base disorder.","labelA":"Increases","labelB":"Decreases","tiles":[{"id":"t1","text":"Urinary bicarbonate excretion","group":"a","why":"Carbonic anhydrase inhibition reduces proximal bicarbonate reclamation."},{"id":"t2","text":"Urine pH","group":"a","why":"Bicarbonate remaining in the urine makes it more alkaline."},{"id":"t3","text":"Urine volume","group":"a","why":"Unreabsorbed solute carries water into the urine."},{"id":"t4","text":"Serum bicarbonate","group":"b","why":"Renal bicarbonate loss lowers its concentration in plasma."},{"id":"t5","text":"Serum pH","group":"b","why":"Bicarbonate loss produces a metabolic acidosis."},{"id":"t6","text":"Proximal bicarbonate reabsorption","group":"b","why":"Carbonic anhydrase inhibition impairs this transport process."}],"explanation":"Urine becomes more alkaline while blood becomes more acidic because bicarbonate is being lost from plasma into urine.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-034","conceptId":"PLX-HYA-S034","systems":["Renal"],"topic":"Prerenal physiology versus acute tubular injury","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Classic patterns without recent diuretics, CKD or glycosuria; interpret urine indices as supportive findings.","labelA":"Prerenal physiology","labelB":"Acute tubular injury","tiles":[{"id":"t1","text":"Fractional sodium excretion below 1%","group":"a","why":"Intact tubules conserve sodium during reduced renal perfusion."},{"id":"t2","text":"BUN-to-creatinine ratio often above 20","group":"a","why":"Enhanced urea reabsorption can raise this ratio."},{"id":"t3","text":"Preserved tubular sodium conservation","group":"a","why":"The main initial problem is reduced perfusion rather than epithelial damage."},{"id":"t4","text":"Fractional sodium excretion often above 2%","group":"b","why":"Damaged tubules may fail to conserve sodium efficiently."},{"id":"t5","text":"Nephrotoxic aminoglycoside injury","group":"b","why":"Aminoglycosides can directly injure tubular epithelial cells."},{"id":"t6","text":"Impaired tubular sodium reabsorption","group":"b","why":"Epithelial injury compromises normal transport function."}],"explanation":"Preserved sodium conservation supports prerenal physiology. Tubular injury can impair that response, but neither urine index establishes the diagnosis alone.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-035","conceptId":"PLX-HYA-S035","systems":["Endocrine","Renal"],"topic":"Untreated diabetic ketoacidosis","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Typical established DKA before treatment; classify expected changes compared with a healthy baseline.","labelA":"Increases","labelB":"Decreases","tiles":[{"id":"t1","text":"Beta-hydroxybutyrate","group":"a","why":"Insulin deficiency promotes production of this major ketone body."},{"id":"t2","text":"Anion gap","group":"a","why":"Accumulated ketoanions increase unmeasured anions."},{"id":"t3","text":"Plasma osmolality","group":"a","why":"Marked hyperglycemia increases plasma osmolality."},{"id":"t4","text":"Serum bicarbonate","group":"b","why":"Buffering of ketoacids consumes bicarbonate."},{"id":"t5","text":"Arterial pH","group":"b","why":"Ketoacid accumulation produces acidemia unless a mixed disorder modifies it."},{"id":"t6","text":"Total-body potassium stores","group":"b","why":"Osmotic diuresis and other losses deplete body potassium."}],"explanation":"DKA combines ketone accumulation, metabolic acidosis and total-body electrolyte losses. Serum potassium can be normal or high despite depleted stores.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-036","conceptId":"PLX-HYA-S036","systems":["Pulmonary","Acid-base"],"topic":"Respiratory alkalosis versus acidosis","tier":0,"prompt":"Sort all six tiles into the two groups.","context":"Isolated primary respiratory disorders; identify the causal ventilation and PaCO2 pattern.","labelA":"Respiratory alkalosis","labelB":"Respiratory acidosis","tiles":[{"id":"t1","text":"Primary fall in PaCO2","group":"a","why":"Excess alveolar ventilation removes more carbon dioxide."},{"id":"t2","text":"Alveolar ventilation exceeds CO2 production","group":"a","why":"Carbon dioxide removal is too high for metabolic production."},{"id":"t3","text":"pH rises from CO2 loss","group":"a","why":"Lower carbon dioxide shifts the buffer system toward alkalemia."},{"id":"t4","text":"Primary rise in PaCO2","group":"b","why":"Insufficient alveolar ventilation retains carbon dioxide."},{"id":"t5","text":"Alveolar ventilation is inadequate","group":"b","why":"Carbon dioxide elimination is too low for metabolic production."},{"id":"t6","text":"pH falls from CO2 retention","group":"b","why":"Higher carbon dioxide increases carbonic acid buffering load."}],"explanation":"PaCO2 reflects alveolar ventilation relative to carbon dioxide production. Respiratory rate alone cannot determine the disorder.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-037","conceptId":"PLX-HYA-S037","systems":["Pulmonary","Acid-base"],"topic":"Respiratory compensation for metabolic disorders","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Appropriate partial respiratory compensation for an isolated metabolic disorder, without pulmonary limitation.","labelA":"Metabolic acidosis compensation","labelB":"Metabolic alkalosis compensation","tiles":[{"id":"t1","text":"Alveolar ventilation rises","group":"a","why":"More ventilation removes carbon dioxide to offset acidemia."},{"id":"t2","text":"PaCO2 falls","group":"a","why":"Greater carbon dioxide clearance reduces its acidifying effect."},{"id":"t3","text":"Deep Kussmaul breathing in severe DKA","group":"a","why":"Deep ventilation is a classic response to severe metabolic acidosis."},{"id":"t4","text":"Alveolar ventilation falls","group":"b","why":"Reduced ventilation retains carbon dioxide to offset alkalemia."},{"id":"t5","text":"PaCO2 rises","group":"b","why":"Retained carbon dioxide increases the acidifying buffer component."},{"id":"t6","text":"Compensatory carbon dioxide retention","group":"b","why":"Carbon dioxide retention partially corrects the primary metabolic alkalosis."}],"explanation":"Respiratory compensation changes PaCO2 in the same direction as the primary bicarbonate change. Compensation generally does not fully normalize pH.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-038","conceptId":"PLX-HYA-S038","systems":["Pulmonary"],"topic":"High versus low regional V/Q","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Classify the regional ventilation-to-perfusion ratio; compare upright lung apex and base with each other.","labelA":"Higher V/Q","labelB":"Lower V/Q","tiles":[{"id":"t1","text":"Ventilated embolized lung region","group":"a","why":"Perfusion falls while ventilation may remain present."},{"id":"t2","text":"Alveolus ventilated but underperfused","group":"a","why":"The denominator falls relative to ventilation."},{"id":"t3","text":"Upright lung apex relative to base","group":"a","why":"Perfusion declines toward the apex more than ventilation does."},{"id":"t4","text":"Perfused alveolus behind an obstructed airway","group":"b","why":"Ventilation falls while blood flow remains present."},{"id":"t5","text":"Alveolus perfused but underventilated","group":"b","why":"The numerator falls relative to perfusion."},{"id":"t6","text":"Upright lung base relative to apex","group":"b","why":"Perfusion increases toward the base more than ventilation does."}],"explanation":"A high V/Q region wastes ventilation. A low V/Q region receives insufficient ventilation for its blood flow.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-039","conceptId":"PLX-HYA-S039","systems":["Pulmonary"],"topic":"Alveolar-arterial oxygen gradient","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Pure mechanisms on room air, without combined lung disease. For sedatives, consider isolated hypoventilation.","labelA":"A-a gradient widened","labelB":"A-a gradient preserved","tiles":[{"id":"t1","text":"Pulmonary embolism","group":"a","why":"V/Q mismatch lowers arterial oxygen relative to the calculated alveolar value."},{"id":"t2","text":"Pulmonary fibrosis","group":"a","why":"Diffusion limitation and V/Q mismatch can impair oxygen transfer."},{"id":"t3","text":"Cardiogenic pulmonary edema","group":"a","why":"Fluid-related V/Q abnormalities impair arterial oxygenation."},{"id":"t4","text":"Pure opioid hypoventilation","group":"b","why":"Both alveolar and arterial oxygen fall from inadequate ventilation."},{"id":"t5","text":"Pure benzodiazepine hypoventilation","group":"b","why":"Isolated reduced ventilation lowers alveolar oxygen without an additional transfer defect."},{"id":"t6","text":"Low inspired oxygen at altitude","group":"b","why":"Reduced inspired oxygen lowers both alveolar and arterial oxygen."}],"explanation":"Hypoventilation and low inspired oxygen can cause hypoxemia with a preserved A-a gradient. Gas-transfer defects or V/Q mismatch widen the gradient.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-040","conceptId":"PLX-HYA-S040","systems":["Pulmonary"],"topic":"Obstructive versus parenchymal restrictive physiology","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare classic emphysema with fibrotic interstitial lung disease; exclude mixed disease.","labelA":"Obstructive pattern","labelB":"Fibrotic restrictive pattern","tiles":[{"id":"t1","text":"FEV1/FVC is reduced","group":"a","why":"Expiratory flow falls disproportionately relative to vital capacity."},{"id":"t2","text":"Residual volume rises","group":"a","why":"Air trapping leaves excess gas after maximal expiration."},{"id":"t3","text":"Emphysema","group":"a","why":"Loss of elastic recoil promotes expiratory airflow limitation."},{"id":"t4","text":"FEV1/FVC is preserved or high","group":"b","why":"FEV1 and FVC fall without the characteristic obstructive ratio reduction."},{"id":"t5","text":"Total lung capacity is reduced","group":"b","why":"Restriction is defined by a reduced total lung capacity."},{"id":"t6","text":"Pulmonary fibrosis","group":"b","why":"Stiffened parenchyma restricts lung expansion."}],"explanation":"The ratio suggests obstruction, while a low total lung capacity confirms restriction. Reduced FVC alone is insufficient to establish restriction.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-041","conceptId":"PLX-HYA-S041","systems":["Pulmonary"],"topic":"Emphysema versus pulmonary fibrosis mechanics","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare intrinsic parenchymal mechanics in classic emphysema and pulmonary fibrosis.","labelA":"Emphysema","labelB":"Pulmonary fibrosis","tiles":[{"id":"t1","text":"Lung compliance rises","group":"a","why":"Destroyed elastic tissue allows easier expansion."},{"id":"t2","text":"Elastic recoil falls","group":"a","why":"Loss of elastic support reduces passive inward recoil."},{"id":"t3","text":"Residual volume rises","group":"a","why":"Poor recoil and airway collapse promote air trapping."},{"id":"t4","text":"Lung compliance falls","group":"b","why":"Fibrotic tissue resists expansion."},{"id":"t5","text":"Elastic recoil rises","group":"b","why":"Stiffened tissue has greater inward recoil."},{"id":"t6","text":"Residual volume tends to fall","group":"b","why":"Reduced lung size generally reduces retained end-expiratory gas volumes."}],"explanation":"Emphysema produces a highly compliant lung with poor recoil. Fibrosis produces a stiff lung with greater recoil.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-042","conceptId":"PLX-HYA-S042","systems":["Pulmonary"],"topic":"Neonatal RDS versus adult ARDS","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Sort the characteristic initiating mechanisms and settings of the two syndromes.","labelA":"Prematurity-related neonatal RDS","labelB":"Adult ARDS","tiles":[{"id":"t1","text":"Premature birth","group":"a","why":"Immature lungs may not yet provide adequate surfactant."},{"id":"t2","text":"Immature type II pneumocytes","group":"a","why":"Surfactant synthesis and storage are insufficiently developed."},{"id":"t3","text":"Primary surfactant deficiency","group":"a","why":"Insufficient surfactant increases alveolar collapse tendency."},{"id":"t4","text":"Diffuse alveolar-capillary barrier injury","group":"b","why":"Increased permeability permits protein-rich fluid to enter alveoli."},{"id":"t5","text":"Severe pancreatitis trigger","group":"b","why":"Systemic inflammation from pancreatitis can precipitate ARDS."},{"id":"t6","text":"Protein-rich alveolar edema","group":"b","why":"Leaky pulmonary microvasculature produces permeability edema."}],"explanation":"Neonatal RDS classically starts with immature surfactant production. ARDS starts with inflammatory permeability injury, which can also disrupt surfactant.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-043","conceptId":"PLX-HYA-S043","systems":["Cardiology","Pulmonary"],"topic":"Left heart failure versus isolated cor pulmonale","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare left-sided pump failure with isolated lung-disease-related right heart failure and a normal left heart.","labelA":"Left-sided heart failure","labelB":"Isolated cor pulmonale","tiles":[{"id":"t1","text":"Pulmonary capillary wedge pressure rises","group":"a","why":"Higher left atrial pressure is transmitted into the pulmonary venous circulation."},{"id":"t2","text":"Left atrial pressure is elevated","group":"a","why":"The left heart cannot accommodate or eject incoming blood normally."},{"id":"t3","text":"Pulmonary venous congestion","group":"a","why":"Backward pressure favors pulmonary edema."},{"id":"t4","text":"Wedge pressure usually remains normal","group":"b","why":"The left atrium is not the source of the pressure problem."},{"id":"t5","text":"Lung disease increases RV afterload","group":"b","why":"Elevated pulmonary vascular load strains the right ventricle."},{"id":"t6","text":"Right failure follows pulmonary disease","group":"b","why":"The initiating process lies in the lung or pulmonary circulation."}],"explanation":"Wedge pressure estimates left atrial pressure when measured appropriately. Isolated cor pulmonale does not require elevated left-sided filling pressure.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-044","conceptId":"PLX-HYA-S044","systems":["Pulmonary"],"topic":"Transudative versus exudative pleural effusion","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Classic uncomplicated mechanisms; exclude diuretic-treated heart failure and mixed pleural disease.","labelA":"Transudative effusion","labelB":"Exudative effusion","tiles":[{"id":"t1","text":"Meets none of Light criteria","group":"a","why":"All three exudative criteria must be absent for this classification."},{"id":"t2","text":"Hydrostatic or oncotic imbalance","group":"a","why":"Fluid accumulates without primary inflammatory pleural injury."},{"id":"t3","text":"Uncomplicated heart failure effusion","group":"a","why":"Elevated hydrostatic pressure can produce a transudate."},{"id":"t4","text":"Meets at least one Light criterion","group":"b","why":"Any single positive criterion classifies the fluid as exudative."},{"id":"t5","text":"Primary pleural inflammation","group":"b","why":"Increased permeability allows protein-rich fluid to accumulate."},{"id":"t6","text":"Parapneumonic effusion","group":"b","why":"Pneumonia-associated pleural inflammation typically produces an exudate."}],"explanation":"Exudates satisfy at least one Light criterion. A single low protein or LDH ratio does not by itself establish a transudate.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-045","conceptId":"PLX-HYA-S045","systems":["Cardiology","Physiology"],"topic":"Baroreflex response to falling pressure","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Immediate intact baroreflex response to a fall in systemic arterial pressure, before long-term compensation.","labelA":"Increases","labelB":"Decreases","tiles":[{"id":"t1","text":"Cardiac sympathetic outflow","group":"a","why":"Reduced baroreceptor input releases sympathetic drive."},{"id":"t2","text":"Sinoatrial firing rate","group":"a","why":"Increased sympathetic and reduced vagal influence increase heart rate."},{"id":"t3","text":"Systemic arteriolar constriction","group":"a","why":"Sympathetic vasoconstriction supports arterial pressure."},{"id":"t4","text":"Carotid sinus stretch","group":"b","why":"Lower arterial pressure reduces distension of the sinus wall."},{"id":"t5","text":"Glossopharyngeal afferent firing","group":"b","why":"Reduced stretch lowers carotid baroreceptor signaling through CN IX."},{"id":"t6","text":"Cardiac vagal outflow","group":"b","why":"Reduced baroreceptor input lowers parasympathetic activity to the heart."}],"explanation":"Baroreceptors respond to stretch. Falling pressure reduces afferent firing and shifts autonomic output toward sympathetic activity.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-046","conceptId":"PLX-HYA-S046","systems":["Cardiology","Endocrine"],"topic":"ANP versus aldosterone","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Sort characteristic sources or actions of these volume-regulating hormones.","labelA":"Atrial natriuretic peptide","labelB":"Aldosterone","tiles":[{"id":"t1","text":"Released with atrial stretch","group":"a","why":"Atrial myocytes release ANP when filling and stretch increase."},{"id":"t2","text":"Promotes natriuresis","group":"a","why":"ANP supports renal sodium excretion."},{"id":"t3","text":"Inhibits renin release","group":"a","why":"ANP counteracts activation of the renin-angiotensin system."},{"id":"t4","text":"Zona glomerulosa source","group":"b","why":"The outer adrenal cortex secretes aldosterone."},{"id":"t5","text":"Promotes distal potassium secretion","group":"b","why":"Aldosterone enhances renal potassium excretion."},{"id":"t6","text":"Promotes distal sodium reabsorption","group":"b","why":"Mineralocorticoid action favors renal sodium retention."}],"explanation":"ANP promotes disposal of a volume load. Aldosterone promotes sodium retention while increasing potassium excretion.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-047","conceptId":"PLX-HYA-S047","systems":["Cardiology"],"topic":"ASD versus VSD oxygen step-up","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Uncomplicated left-to-right defects before pulmonary vascular shunt reversal.","labelA":"Atrial septal defect","labelB":"Ventricular septal defect","tiles":[{"id":"t1","text":"First oxygen step-up in right atrium","group":"a","why":"Oxygenated left atrial blood enters the right atrium."},{"id":"t2","text":"Fixed splitting of S2","group":"a","why":"Persistent increased right-sided flow produces the classic fixed split."},{"id":"t3","text":"Left atrium to right atrium shunt","group":"a","why":"The communication lies at the atrial level."},{"id":"t4","text":"First oxygen step-up in right ventricle","group":"b","why":"Oxygenated left ventricular blood enters the right ventricle."},{"id":"t5","text":"Holosystolic lower-left-sternal murmur","group":"b","why":"Flow through the ventricular defect produces this classic murmur."},{"id":"t6","text":"Left ventricle to right ventricle shunt","group":"b","why":"The communication lies at the ventricular level."}],"explanation":"The first chamber with an oxygen saturation step-up localizes a left-to-right shunt. Downstream chambers may also show elevated oxygen.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-048","conceptId":"PLX-HYA-S048","systems":["Cardiology"],"topic":"Systolic versus diastolic dysfunction","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare classic reduced-EF systolic dysfunction with preserved-EF diastolic dysfunction.","labelA":"Systolic dysfunction","labelB":"Diastolic dysfunction","tiles":[{"id":"t1","text":"Reduced ejection fraction","group":"a","why":"A smaller proportion of end-diastolic volume is ejected."},{"id":"t2","text":"Impaired ventricular contraction","group":"a","why":"The main functional defect is reduced pumping force."},{"id":"t3","text":"Dilated LV is characteristic","group":"a","why":"A dilated ventricle is a classic structural pattern."},{"id":"t4","text":"Ejection fraction is preserved","group":"b","why":"A preserved fraction can coexist with impaired filling."},{"id":"t5","text":"Impaired relaxation or compliance","group":"b","why":"The ventricle requires more pressure to fill adequately."},{"id":"t6","text":"Stiff LV is characteristic","group":"b","why":"Hypertrophy or infiltration can impair filling."}],"explanation":"Reduced contractile emptying lowers ejection fraction. Diastolic dysfunction can elevate filling pressures despite a preserved ejection fraction.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-049","conceptId":"PLX-HYA-S049","systems":["Cardiology"],"topic":"Hypovolemic versus cardiogenic shock","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classic unresuscitated hemorrhagic shock versus left-ventricular pump-failure shock; exclude mixed shock.","labelA":"Hypovolemic shock","labelB":"Cardiogenic shock","tiles":[{"id":"t1","text":"Loss of circulating blood volume","group":"a","why":"Hemorrhage reduces available intravascular volume."},{"id":"t2","text":"Wedge pressure is typically low","group":"a","why":"Left-sided filling falls with inadequate venous return."},{"id":"t3","text":"Inadequate preload is primary","group":"a","why":"Insufficient filling limits cardiac output."},{"id":"t4","text":"Primary ventricular pump failure","group":"b","why":"The heart cannot maintain forward flow despite available volume."},{"id":"t5","text":"Wedge pressure is typically high","group":"b","why":"Left-sided filling pressure rises behind the failing pump."},{"id":"t6","text":"Pulmonary venous congestion may develop","group":"b","why":"Backward pressure can drive fluid into the lungs."}],"explanation":"Both can have low cardiac output and compensatory high systemic resistance. Their classic filling-pressure patterns differ.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-050","conceptId":"PLX-HYA-S050","systems":["Cardiology","Pharmacology"],"topic":"Systemic vascular resistance directions","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Classify the characteristic direct or compensatory SVR effect in the specified setting.","labelA":"SVR decreases","labelB":"SVR increases","tiles":[{"id":"t1","text":"Warm hyperdynamic septic shock","group":"a","why":"Inflammatory vasodilation lowers systemic vascular resistance."},{"id":"t2","text":"Anaphylactic vasodilation","group":"a","why":"Mediator release can produce profound systemic vasodilation."},{"id":"t3","text":"Nifedipine arteriolar action","group":"a","why":"Dihydropyridine calcium channel blockade relaxes systemic arterioles."},{"id":"t4","text":"Hemorrhagic shock compensation","group":"b","why":"Sympathetic vasoconstriction supports arterial pressure during low volume."},{"id":"t5","text":"LV cardiogenic shock compensation","group":"b","why":"Reduced forward output triggers systemic vasoconstriction."},{"id":"t6","text":"Phenylephrine alpha-1 action","group":"b","why":"Alpha-1 receptor activation directly constricts systemic arterioles."}],"explanation":"Vasodilatory shock lowers resistance. Low-volume and low-output shock commonly provoke compensatory vasoconstriction.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-051","conceptId":"PLX-HYA-S051","systems":["Hematology"],"topic":"Primary versus secondary hemostasis","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classify the main process or characteristic bleeding pattern.","labelA":"Primary hemostasis","labelB":"Secondary hemostasis","tiles":[{"id":"t1","text":"Platelet adhesion to injured vessel","group":"a","why":"Platelets attach to exposed subendothelial structures."},{"id":"t2","text":"Platelet aggregation","group":"a","why":"Activated platelets bind to one another to form a plug."},{"id":"t3","text":"Typical mucocutaneous bleeding pattern","group":"a","why":"Platelet defects commonly cause petechiae, epistaxis or mucosal bleeding."},{"id":"t4","text":"Fibrin formation","group":"b","why":"Coagulation converts fibrinogen into a stabilizing fibrin network."},{"id":"t5","text":"Coagulation factor cascade","group":"b","why":"Sequential factor activation generates thrombin and fibrin."},{"id":"t6","text":"Typical hemarthrosis pattern","group":"b","why":"Severe factor deficiencies commonly cause deep tissue and joint bleeding."}],"explanation":"The platelet plug is primary hemostasis. Coagulation-generated fibrin stabilizes it during secondary hemostasis.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-052","conceptId":"PLX-HYA-S052","systems":["Hematology"],"topic":"ITP versus hemophilia","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Classic immune thrombocytopenia versus clinically significant hemophilia without a second disorder.","labelA":"Immune thrombocytopenia","labelB":"Hemophilia","tiles":[{"id":"t1","text":"Platelet count is low","group":"a","why":"Immune-mediated platelet destruction causes thrombocytopenia."},{"id":"t2","text":"PT and aPTT are usually normal","group":"a","why":"The primary problem is platelet number rather than coagulation factor activity."},{"id":"t3","text":"Petechiae and mucosal bleeding","group":"a","why":"Low platelets impair primary hemostasis."},{"id":"t4","text":"Platelet count is preserved","group":"b","why":"The primary defect is a coagulation factor deficiency."},{"id":"t5","text":"aPTT is typically prolonged","group":"b","why":"Deficiency of factor VIII or IX impairs the intrinsic pathway assay."},{"id":"t6","text":"Hemarthroses","group":"b","why":"Joint bleeding is a classic manifestation of significant factor deficiency."}],"explanation":"ITP affects platelets. Hemophilia A or B affects intrinsic-pathway factor activity.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-053","conceptId":"PLX-HYA-S053","systems":["Hematology","Renal"],"topic":"ITP versus uremic platelet dysfunction","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare isolated immune thrombocytopenia with classic uremic qualitative platelet dysfunction.","labelA":"Immune thrombocytopenia","labelB":"Uremic platelet dysfunction","tiles":[{"id":"t1","text":"Reduced platelet number","group":"a","why":"Platelet destruction lowers the circulating count."},{"id":"t2","text":"Immune platelet clearance","group":"a","why":"Autoantibody-mediated clearance is a central mechanism."},{"id":"t3","text":"Postviral childhood thrombocytopenia","group":"a","why":"ITP can follow a viral illness in a child."},{"id":"t4","text":"Count can be normal despite bleeding","group":"b","why":"Platelet quality rather than quantity may be impaired."},{"id":"t5","text":"Toxin-associated platelet impairment","group":"b","why":"Uremic factors impair platelet adhesion and aggregation."},{"id":"t6","text":"Advanced kidney disease bleeding","group":"b","why":"Uremia can cause an acquired primary-hemostasis defect."}],"explanation":"A normal platelet count does not guarantee normal platelet function. Uremia can impair function without causing thrombocytopenia.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-054","conceptId":"PLX-HYA-S054","systems":["Hematology"],"topic":"von Willebrand disease versus hemophilia A","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare classic inherited vWD with hemophilia A; severe vWD phenotypes can overlap clinically.","labelA":"von Willebrand disease","labelB":"Hemophilia A","tiles":[{"id":"t1","text":"Deficient or dysfunctional vWF","group":"a","why":"The bridging protein required for normal platelet adhesion is affected."},{"id":"t2","text":"Impaired GPIb-mediated adhesion","group":"a","why":"vWF links platelet GPIb to exposed subendothelial structures."},{"id":"t3","text":"Often autosomal dominant inheritance","group":"a","why":"Most common forms have an autosomal dominant pattern."},{"id":"t4","text":"Factor VIII gene defect","group":"b","why":"The inherited defect directly affects factor VIII."},{"id":"t5","text":"X-linked recessive inheritance","group":"b","why":"The classic inheritance pattern follows the X chromosome."},{"id":"t6","text":"Primary factor VIII activity deficiency","group":"b","why":"The main defect is deficient factor VIII rather than a primary vWF defect."}],"explanation":"vWF supports platelet adhesion and stabilizes factor VIII. Hemophilia A directly affects factor VIII, explaining some shared laboratory findings.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-055","conceptId":"PLX-HYA-S055","systems":["Hematology"],"topic":"DIC laboratory changes","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Typical overt consumptive DIC before replacement therapy; classify the expected direction.","labelA":"Increases","labelB":"Decreases","tiles":[{"id":"t1","text":"D-dimer","group":"a","why":"More cross-linked fibrin is formed and degraded."},{"id":"t2","text":"Prothrombin time","group":"a","why":"Consumption of coagulation factors can prolong PT."},{"id":"t3","text":"Activated partial thromboplastin time","group":"a","why":"Consumption of multiple factors can prolong aPTT."},{"id":"t4","text":"Platelet count","group":"b","why":"Platelets are consumed in widespread coagulation."},{"id":"t5","text":"Fibrinogen","group":"b","why":"Conversion and consumption can lower circulating fibrinogen."},{"id":"t6","text":"Available coagulation factors","group":"b","why":"Ongoing activation consumes factor reserves."}],"explanation":"DIC can cause thrombosis and bleeding together because uncontrolled coagulation consumes platelets and factors while fibrin breakdown increases.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-056","conceptId":"PLX-HYA-S056","systems":["Hematology"],"topic":"Iron deficiency versus anemia of inflammation","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare isolated iron deficiency with anemia of inflammation; exclude combined deficiency and recent transfusion.","labelA":"Iron deficiency anemia","labelB":"Anemia of inflammation","tiles":[{"id":"t1","text":"Ferritin is low","group":"a","why":"Depleted iron stores reduce the storage marker."},{"id":"t2","text":"Transferrin tends to rise","group":"a","why":"The liver increases iron-binding capacity when stores are depleted."},{"id":"t3","text":"Body iron stores are depleted","group":"a","why":"Absolute lack of iron limits erythropoiesis."},{"id":"t4","text":"Ferritin is normal or high","group":"b","why":"Stored iron is retained and ferritin also behaves as an acute-phase reactant."},{"id":"t5","text":"Transferrin tends to fall","group":"b","why":"Inflammation reduces this negative acute-phase protein."},{"id":"t6","text":"Iron is sequestered despite stores","group":"b","why":"Inflammatory iron restriction limits availability for erythropoiesis."}],"explanation":"Both can reduce serum iron. Storage and transport patterns help distinguish absolute iron loss from inflammatory iron restriction.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-057","conceptId":"PLX-HYA-S057","systems":["Hematology"],"topic":"Iron deficiency versus thalassemia trait","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Classic isolated iron deficiency versus untreated thalassemia trait without coexisting deficiency or transfusion.","labelA":"Iron deficiency anemia","labelB":"Thalassemia trait","tiles":[{"id":"t1","text":"RDW commonly rises","group":"a","why":"Uneven iron restriction produces greater variation in red cell size."},{"id":"t2","text":"Ferritin is low","group":"a","why":"The iron storage pool is depleted."},{"id":"t3","text":"Serum iron tends to be low","group":"a","why":"There is reduced iron availability for hemoglobin production."},{"id":"t4","text":"RDW is often normal","group":"b","why":"Inherited globin underproduction can produce relatively uniform microcytosis."},{"id":"t5","text":"Iron stores are usually preserved","group":"b","why":"The primary defect is globin synthesis rather than iron depletion."},{"id":"t6","text":"Globin chain production is reduced","group":"b","why":"A genetic synthesis defect produces the microcytosis."}],"explanation":"Microcytosis can result from iron depletion or globin synthesis defects. RDW and iron studies help, but no single pattern is absolute.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-058","conceptId":"PLX-HYA-S058","systems":["Gastrointestinal","Hematology"],"topic":"Predominantly indirect versus direct hyperbilirubinemia","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Sort classic predominant bilirubin patterns before secondary complications or mixed liver injury.","labelA":"Predominantly indirect","labelB":"Predominantly direct","tiles":[{"id":"t1","text":"Gilbert syndrome","group":"a","why":"Reduced bilirubin conjugation raises unconjugated bilirubin."},{"id":"t2","text":"G6PD-related hemolysis","group":"a","why":"Increased red cell breakdown increases the unconjugated bilirubin load."},{"id":"t3","text":"Hereditary spherocytosis hemolysis","group":"a","why":"Accelerated red cell turnover increases unconjugated bilirubin production."},{"id":"t4","text":"Common bile duct stone","group":"b","why":"Obstruction impairs excretion of conjugated bilirubin into bile."},{"id":"t5","text":"Biliary atresia","group":"b","why":"Obstructed bile flow causes conjugated hyperbilirubinemia."},{"id":"t6","text":"Pancreatic head mass obstructing bile duct","group":"b","why":"Mechanical outflow obstruction retains conjugated bilirubin."}],"explanation":"Increased production or reduced conjugation favors indirect bilirubin. Impaired biliary excretion favors direct bilirubin.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-059","conceptId":"PLX-HYA-S059","systems":["Biochemistry"],"topic":"Fed versus fasting hepatic enzyme activity","tier":2,"prompt":"Sort all six tiles into the two groups.","context":"Compare insulin-dominant fed liver with glucagon-dominant fasting liver; consider the overall regulation of activity.","labelA":"Favored in fed liver","labelB":"Favored in fasting liver","tiles":[{"id":"t1","text":"Glycogen synthase","group":"a","why":"The fed state favors storage of glucose as glycogen."},{"id":"t2","text":"Glucokinase","group":"a","why":"Hepatic glucose phosphorylation supports utilization and storage after feeding."},{"id":"t3","text":"PFK-2 kinase activity","group":"a","why":"Increased fructose-2,6-bisphosphate favors hepatic glycolysis."},{"id":"t4","text":"Glycogen phosphorylase","group":"b","why":"Glycogen breakdown supports blood glucose during fasting."},{"id":"t5","text":"PEP carboxykinase","group":"b","why":"Gluconeogenesis supports glucose production during fasting."},{"id":"t6","text":"Glucose-6-phosphatase","group":"b","why":"The liver releases free glucose from glucose-6-phosphate."}],"explanation":"Fed liver uses and stores glucose. Fasting liver increases glucose output through glycogenolysis and gluconeogenesis.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SPL-060","conceptId":"PLX-HYA-S060","systems":["Biochemistry"],"topic":"Glucokinase versus ordinary hexokinase","tier":1,"prompt":"Sort all six tiles into the two groups.","context":"Compare hepatic glucokinase with a typical low-Km tissue hexokinase using the simplified Michaelis-Menten comparison.","labelA":"Glucokinase","labelB":"Typical tissue hexokinase","tiles":[{"id":"t1","text":"Higher apparent Km","group":"a","why":"A higher glucose concentration is needed to reach half-maximal velocity."},{"id":"t2","text":"Higher glucose-processing capacity","group":"a","why":"The classic comparison assigns glucokinase a higher Vmax."},{"id":"t3","text":"Well suited to a high-glucose fed state","group":"a","why":"Its lower affinity helps the liver process abundant glucose after meals."},{"id":"t4","text":"Lower Km","group":"b","why":"The enzyme binds and processes glucose effectively at lower concentrations."},{"id":"t5","text":"Lower capacity in the classic comparison","group":"b","why":"The standard teaching comparison assigns a lower Vmax than glucokinase."},{"id":"t6","text":"Supports use when glucose is scarce","group":"b","why":"High affinity helps tissues use glucose at lower blood concentrations."}],"explanation":"A higher Km corresponds to lower substrate affinity in the simplified comparison. Capacity and affinity are separate properties.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}}],"sequence":[{"contentId":"PLX-HYA-SEQ-001","conceptId":"PLX-HYA-C001","systems":["Renal","Endocrine"],"topic":"RAAS cascade","tier":1,"prompt":"Put the four selected steps in order.","context":"Order selected stages of the renin-angiotensin-aldosterone cascade. Intermediate receptor signals are omitted.","steps":[{"id":"s1","text":"Angiotensinogen","why":"Liver-derived angiotensinogen is the substrate for renin."},{"id":"s2","text":"Angiotensin I","why":"Renin cleaves angiotensinogen to angiotensin I."},{"id":"s3","text":"Angiotensin II","why":"ACE converts angiotensin I to angiotensin II."},{"id":"s4","text":"Aldosterone release","why":"Angiotensin II stimulates zona glomerulosa aldosterone secretion."}],"explanation":"Renin acts first on angiotensinogen. ACE then forms angiotensin II, which stimulates aldosterone release.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-002","conceptId":"PLX-HYA-C002","systems":["Renal","Endocrine"],"topic":"Aldosterone sodium-retaining mechanism","tier":1,"prompt":"Put the four selected steps in order.","context":"Order the selected direct mineralocorticoid pathway with adequate sodium and water availability.","steps":[{"id":"s1","text":"Mineralocorticoid receptor is activated","why":"Aldosterone activates intracellular mineralocorticoid receptors."},{"id":"s2","text":"Distal sodium transport capacity rises","why":"ENaC and basolateral sodium-potassium ATPase support distal sodium transport."},{"id":"s3","text":"Distal sodium reabsorption rises","why":"More sodium moves from tubular fluid back into the body."},{"id":"s4","text":"Extracellular volume expands","why":"Retained sodium with available water expands extracellular volume."}],"explanation":"Mineralocorticoid signaling increases distal sodium reabsorption. Associated water retention supports volume expansion.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-003","conceptId":"PLX-HYA-C003","systems":["Endocrine"],"topic":"ACTH-driven adrenal pigmentation","tier":2,"prompt":"Put the four selected steps in order.","context":"Primary adrenal cortisol deficiency with a functioning pituitary. Order the selected pigmentation pathway.","steps":[{"id":"s1","text":"Adrenal cortisol output falls","why":"Adrenal disease reduces cortisol production."},{"id":"s2","text":"Pituitary ACTH secretion rises","why":"Reduced cortisol feedback increases ACTH production."},{"id":"s3","text":"Melanocortin signaling increases","why":"Elevated ACTH and related POMC products increase melanocortin activity."},{"id":"s4","text":"Skin hyperpigmentation develops","why":"Increased melanocyte stimulation can darken the skin."}],"explanation":"Loss of cortisol feedback raises ACTH. Increased melanocortin activity explains why pigmentation suggests primary rather than isolated central adrenal failure.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-004","conceptId":"PLX-HYA-C004","systems":["Endocrine","Renal"],"topic":"ADH collecting duct action","tier":1,"prompt":"Put the four selected steps in order.","context":"Normal V2 responsiveness, intact medullary gradient and adequate collecting duct flow. Order the selected ADH pathway.","steps":[{"id":"s1","text":"ADH activates collecting duct V2 receptors","why":"ADH binds V2 receptors on collecting duct principal cells."},{"id":"s2","text":"Apical aquaporin-2 insertion increases","why":"Signaling moves aquaporin-2 water channels to the apical membrane."},{"id":"s3","text":"Water permeability rises","why":"Additional channels allow more water to leave the tubular lumen."},{"id":"s4","text":"Urine becomes more concentrated","why":"Water reabsorption increases the concentration of remaining urine."}],"explanation":"ADH increases collecting duct water permeability through aquaporin-2. With an intact gradient, water is reabsorbed and the urine concentrates.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-005","conceptId":"PLX-HYA-C005","systems":["Endocrine"],"topic":"Destructive thyroiditis feedback","tier":1,"prompt":"Put the four selected steps in order.","context":"Thyrotoxic phase of destructive thyroiditis. Order the selected causal steps.","steps":[{"id":"s1","text":"Thyroid follicles are injured","why":"Inflammatory injury disrupts hormone-storing follicles."},{"id":"s2","text":"Stored thyroid hormone is released","why":"Preformed hormone leaks into the circulation."},{"id":"s3","text":"Circulating free thyroid hormone rises","why":"The released hormone transiently raises circulating levels."},{"id":"s4","text":"Pituitary TSH secretion falls","why":"Negative feedback suppresses pituitary TSH."}],"explanation":"Inflammation releases stored hormone. Negative feedback then lowers TSH, while radioiodine uptake remains low during the thyrotoxic phase.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-006","conceptId":"PLX-HYA-C006","systems":["Endocrine"],"topic":"TBG feedback adaptation","tier":2,"prompt":"Put the four selected steps in order.","context":"Conceptual response to an isolated abrupt rise in TBG, with an intact thyroid axis; order the transient feedback steps.","steps":[{"id":"s1","text":"Thyroid-binding globulin rises","why":"The blood gains additional thyroid hormone binding capacity."},{"id":"s2","text":"Free T4 transiently falls","why":"More T4 is initially bound, reducing the free fraction."},{"id":"s3","text":"Pituitary TSH transiently rises","why":"Reduced free-hormone feedback permits a temporary TSH increase."},{"id":"s4","text":"Thyroid hormone synthesis increases","why":"TSH drives additional hormone production until free hormone is restored."}],"explanation":"More binding initially lowers free T4. Feedback increases hormone production, restoring free hormone while total T4 remains higher.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-007","conceptId":"PLX-HYA-C007","systems":["Endocrine","Musculoskeletal"],"topic":"PTH activates bone resorption indirectly","tier":2,"prompt":"Put the four selected steps in order.","context":"Selected pathway during sustained PTH signaling; intermediate osteoclast differentiation signals are omitted.","steps":[{"id":"s1","text":"PTH stimulates osteoblast-lineage cells","why":"PTH acts on osteoblast-lineage cells rather than directly driving mature osteoclast PTH receptors."},{"id":"s2","text":"RANKL signaling increases","why":"These cells increase the osteoclast-promoting RANKL signal."},{"id":"s3","text":"Osteoclast activation increases","why":"RANKL promotes osteoclast development and activity."},{"id":"s4","text":"Bone resorption increases","why":"Activated osteoclasts resorb mineralized bone."}],"explanation":"PTH communicates through osteoblast-lineage cells to increase RANKL-mediated osteoclast activity.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-008","conceptId":"PLX-HYA-C008","systems":["Endocrine","Biochemistry"],"topic":"Vitamin D activation route","tier":1,"prompt":"Put the four selected steps in order.","context":"Order selected stages of cutaneous vitamin D3 formation and activation. Previtamin and transport steps are omitted.","steps":[{"id":"s1","text":"UVB acts on skin 7-dehydrocholesterol","why":"UVB initiates conversion of 7-dehydrocholesterol in skin."},{"id":"s2","text":"Skin forms cholecalciferol","why":"Cutaneous processing yields vitamin D3, also called cholecalciferol."},{"id":"s3","text":"Liver forms 25-hydroxyvitamin D","why":"Hepatic hydroxylation forms calcidiol, the major circulating 25-hydroxy form."},{"id":"s4","text":"Kidney forms 1,25-dihydroxyvitamin D","why":"Renal 1-alpha-hydroxylation forms calcitriol."}],"explanation":"The selected route is skin vitamin D3 formation, hepatic 25-hydroxylation, then renal 1-alpha-hydroxylation.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-009","conceptId":"PLX-HYA-C009","systems":["Renal","Endocrine"],"topic":"CKD calcitriol-calcium-PTH pathway","tier":2,"prompt":"Put the four selected steps in order.","context":"Selected vitamin D pathway in advanced untreated CKD; phosphate retention is an additional parallel contributor.","steps":[{"id":"s1","text":"Functioning renal tissue declines","why":"Advanced kidney disease reduces functioning renal tissue."},{"id":"s2","text":"Renal calcitriol production falls","why":"Renal activation of vitamin D is impaired."},{"id":"s3","text":"Intestinal calcium absorption falls","why":"Lower calcitriol reduces support for calcium absorption."},{"id":"s4","text":"Secondary PTH secretion increases","why":"The resulting calcium-vitamin D disturbance contributes to secondary hyperparathyroidism."}],"explanation":"Reduced renal calcitriol production contributes to impaired calcium absorption and secondary PTH elevation.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-010","conceptId":"PLX-HYA-C010","systems":["Endocrine","Pulmonary"],"topic":"Sarcoid calcitriol hypercalcemia","tier":2,"prompt":"Put the four selected steps in order.","context":"Sarcoidosis with calcitriol-mediated hypercalcemia. Order the selected pathway; serum calcium elevation is implicit before PTH suppression.","steps":[{"id":"s1","text":"Granuloma macrophage 1-alpha activity rises","why":"Activated granuloma macrophages express extrarenal 1-alpha-hydroxylase."},{"id":"s2","text":"Calcitriol production rises","why":"More 25-hydroxyvitamin D is converted to calcitriol."},{"id":"s3","text":"Intestinal calcium absorption rises","why":"Calcitriol promotes intestinal calcium uptake."},{"id":"s4","text":"Endogenous PTH secretion falls","why":"Hypercalcemia feeds back to suppress parathyroid PTH secretion."}],"explanation":"Extrarenal calcitriol generation raises intestinal calcium absorption. The resulting hypercalcemia suppresses endogenous PTH.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-011","conceptId":"PLX-HYA-C011","systems":["Reproductive","Endocrine"],"topic":"Ovarian failure feedback","tier":1,"prompt":"Put the four selected steps in order.","context":"Established primary ovarian failure. Order the selected loss-of-feedback pathway.","steps":[{"id":"s1","text":"Ovarian follicular function declines","why":"Declining follicular function reduces ovarian endocrine output."},{"id":"s2","text":"Estrogen and inhibin secretion fall","why":"The ovaries supply less estrogen and inhibin."},{"id":"s3","text":"Pituitary negative feedback weakens","why":"The pituitary receives less inhibitory feedback."},{"id":"s4","text":"FSH secretion increases","why":"Pituitary FSH rises in response to the lost feedback."}],"explanation":"Reduced ovarian estrogen and inhibin remove negative feedback, allowing gonadotropins, especially FSH, to rise.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-012","conceptId":"PLX-HYA-C012","systems":["Reproductive","Endocrine"],"topic":"Male LH-testosterone signaling","tier":1,"prompt":"Put the four selected steps in order.","context":"Normal male hypothalamic-pituitary-gonadal axis. Order the selected stimulatory signals.","steps":[{"id":"s1","text":"Hypothalamic GnRH pulse occurs","why":"Pulsatile GnRH reaches pituitary gonadotrophs."},{"id":"s2","text":"Pituitary LH is released","why":"The pituitary responds by releasing LH."},{"id":"s3","text":"Testicular Leydig cells are stimulated","why":"LH activates its receptor on Leydig cells."},{"id":"s4","text":"Testosterone synthesis increases","why":"Stimulated Leydig cells increase testosterone production."}],"explanation":"GnRH drives pituitary LH release. LH stimulates Leydig cells to produce testosterone.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-013","conceptId":"PLX-HYA-C013","systems":["Endocrine","Pharmacology"],"topic":"D2 blockade and reproductive suppression","tier":2,"prompt":"Put the four selected steps in order.","context":"Sustained D2 antagonist exposure with clinically significant hyperprolactinemia. Order the selected pathway.","steps":[{"id":"s1","text":"Pituitary D2 receptors are blocked","why":"Blocking dopamine removes tonic inhibition from lactotrophs."},{"id":"s2","text":"Prolactin secretion rises","why":"Disinhibited lactotrophs release more prolactin."},{"id":"s3","text":"GnRH pulsatility declines","why":"Sustained hyperprolactinemia suppresses hypothalamic reproductive signaling."},{"id":"s4","text":"Gonadotropin drive declines","why":"Reduced GnRH drive can lower LH and FSH secretion."}],"explanation":"Dopamine normally suppresses prolactin. Removing that inhibition can raise prolactin enough to suppress the gonadal axis.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-014","conceptId":"PLX-HYA-C014","systems":["Reproductive","Endocrine"],"topic":"Exogenous androgen feedback","tier":2,"prompt":"Put the four selected steps in order.","context":"Sustained exogenous androgen exposure. Order a selected pathway that can impair spermatogenesis.","steps":[{"id":"s1","text":"Exogenous androgen exposure increases","why":"Exogenous androgen increases negative feedback on the hypothalamic-pituitary axis."},{"id":"s2","text":"Pituitary LH secretion falls","why":"Reduced central drive lowers LH stimulation of Leydig cells."},{"id":"s3","text":"Intratesticular testosterone falls","why":"Less Leydig stimulation reduces the high local testosterone concentration."},{"id":"s4","text":"Spermatogenesis can decline","why":"Low intratesticular testosterone contributes to impaired sperm production."}],"explanation":"Exogenous androgen can raise circulating androgen while suppressing endogenous gonadotropins and local testicular testosterone.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-015","conceptId":"PLX-HYA-C015","systems":["Renal","Pharmacology"],"topic":"Loop diuretic contraction alkalosis","tier":2,"prompt":"Put the four selected steps in order.","context":"A loop diuretic causes effective volume contraction. Order the selected sequence; changes can overlap in real time.","steps":[{"id":"s1","text":"Loop diuretic inhibits NKCC2","why":"Transport inhibition reduces salt reclamation in the thick ascending limb."},{"id":"s2","text":"Urinary sodium and water loss increases","why":"More sodium and water are excreted."},{"id":"s3","text":"Renin-angiotensin drive increases","why":"Effective volume contraction stimulates the renin-angiotensin-aldosterone system."},{"id":"s4","text":"Distal hydrogen secretion increases","why":"Aldosterone activity and distal delivery favor hydrogen secretion and alkalosis."}],"explanation":"Loop-induced salt and water loss can activate RAAS, increasing distal hydrogen loss and sustaining metabolic alkalosis.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-016","conceptId":"PLX-HYA-C016","systems":["Renal","Pharmacology"],"topic":"Acetazolamide bicarbonaturia","tier":1,"prompt":"Put the four selected steps in order.","context":"Early effect of acetazolamide with preserved kidney function. Order the selected urinary pathway.","steps":[{"id":"s1","text":"Renal carbonic anhydrase is inhibited","why":"The drug inhibits carbonic anhydrase supporting proximal acid-base transport."},{"id":"s2","text":"Proximal bicarbonate reclamation falls","why":"Filtered bicarbonate is reclaimed less effectively."},{"id":"s3","text":"Urinary bicarbonate excretion rises","why":"More bicarbonate remains in the tubular fluid and is excreted."},{"id":"s4","text":"Urine pH rises","why":"Excreted bicarbonate makes the urine more alkaline."}],"explanation":"Acetazolamide causes bicarbonate loss into urine. Urine pH rises while plasma bicarbonate falls.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-017","conceptId":"PLX-HYA-C017","systems":["Endocrine","Biochemistry"],"topic":"DKA ketone-acid pathway","tier":1,"prompt":"Put the four selected steps in order.","context":"Severe insulin deficiency with unchecked ketogenesis. Order the selected sequence; glucagon drive is implicit.","steps":[{"id":"s1","text":"Insulin action falls","why":"Insulin deficiency releases normal restraint on fuel mobilization."},{"id":"s2","text":"Adipose lipolysis increases","why":"Fatty acids are released from adipose stores."},{"id":"s3","text":"Hepatic ketone production increases","why":"The liver converts fatty-acid-derived substrate into ketone bodies."},{"id":"s4","text":"Plasma bicarbonate falls","why":"Buffering the accumulating ketoacids consumes bicarbonate."}],"explanation":"Low insulin and counterregulatory signaling increase lipolysis and ketogenesis. Ketoacid buffering lowers bicarbonate.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-018","conceptId":"PLX-HYA-C018","systems":["Endocrine","Renal"],"topic":"Hyperglycemic osmotic diuresis","tier":1,"prompt":"Put the four selected steps in order.","context":"Hyperglycemia exceeds renal glucose reabsorptive capacity. Order the selected tubular water-loss pathway.","steps":[{"id":"s1","text":"Plasma glucose rises markedly","why":"Marked plasma hyperglycemia raises the filtered glucose load."},{"id":"s2","text":"Filtered glucose exceeds reabsorption","why":"Transport capacity is exceeded, so glucose remains in the lumen."},{"id":"s3","text":"Glucose retains water in tubular fluid","why":"Unreabsorbed glucose acts as an osmole within tubular fluid."},{"id":"s4","text":"Osmotic diuresis develops","why":"Increased solute-associated water excretion causes polyuria."}],"explanation":"Glucosuria retains water in the tubular lumen, producing osmotic diuresis and contributing to volume and electrolyte losses.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-019","conceptId":"PLX-HYA-C019","systems":["Endocrine","Nutrition"],"topic":"Refeeding hypophosphatemia","tier":1,"prompt":"Put the four selected steps in order.","context":"A person with depleted stores receives substantial carbohydrate after prolonged undernutrition. Order the selected pathway.","steps":[{"id":"s1","text":"Carbohydrate feeding resumes","why":"Carbohydrate availability stimulates an anabolic transition."},{"id":"s2","text":"Insulin secretion increases","why":"The pancreas releases insulin in response to the carbohydrate load."},{"id":"s3","text":"Cellular phosphate uptake and use rise","why":"Cells take up and use phosphate for phosphorylated intermediates and energy metabolism."},{"id":"s4","text":"Serum phosphate falls","why":"Extracellular phosphate can fall substantially when stores are depleted."}],"explanation":"Carbohydrate-driven insulin release promotes cellular uptake and use of phosphate. Depleted stores make a dangerous serum phosphate fall more likely.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-020","conceptId":"PLX-HYA-C020","systems":["Pulmonary","Neurology"],"topic":"Hyperventilation and cerebral blood flow","tier":2,"prompt":"Put the four selected steps in order.","context":"Acute hyperventilation with stable oxygen delivery and no overriding cerebrovascular pathology.","steps":[{"id":"s1","text":"Alveolar ventilation rises","why":"Increased alveolar ventilation removes more carbon dioxide."},{"id":"s2","text":"Arterial PaCO2 falls","why":"Carbon dioxide elimination exceeds its production."},{"id":"s3","text":"Cerebral arterioles constrict","why":"Hypocapnia produces cerebral vasoconstriction."},{"id":"s4","text":"Cerebral blood flow falls","why":"Increased cerebrovascular resistance reduces cerebral perfusion."}],"explanation":"Hypocapnia constricts cerebral vessels and can contribute to lightheadedness during hyperventilation.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-021","conceptId":"PLX-HYA-C021","systems":["Pulmonary","Genetics"],"topic":"Alpha-1-antitrypsin emphysema pathway","tier":1,"prompt":"Put the four selected steps in order.","context":"Selected pulmonary mechanism of alpha-1-antitrypsin deficiency; intermediate inflammatory events are omitted.","steps":[{"id":"s1","text":"Alpha-1-antitrypsin protection falls","why":"The lung loses an important inhibitor of protease injury."},{"id":"s2","text":"Elastase activity becomes unopposed","why":"Insufficient inhibition permits excess elastase-mediated damage."},{"id":"s3","text":"Alveolar walls are damaged","why":"Proteolysis destroys alveolar walls and elastic support."},{"id":"s4","text":"Emphysematous air trapping develops","why":"Loss of recoil and airway support promotes emphysema and trapping."}],"explanation":"Alpha-1-antitrypsin inhibits elastase. Reduced protection allows protease-mediated tissue destruction and emphysema.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-022","conceptId":"PLX-HYA-C022","systems":["Pulmonary"],"topic":"Surfactant deficiency mechanics","tier":1,"prompt":"Put the four selected steps in order.","context":"Prematurity-related surfactant deficiency. Order selected mechanical consequences.","steps":[{"id":"s1","text":"Surfactant availability falls","why":"Immature type II pneumocytes provide insufficient surfactant."},{"id":"s2","text":"Alveolar surface tension rises","why":"Less surfactant leaves a larger air-liquid surface tension."},{"id":"s3","text":"Alveolar collapse tendency rises","why":"Higher surface tension makes alveoli less stable."},{"id":"s4","text":"Lung compliance falls","why":"More pressure is required to expand the poorly stabilized lung."}],"explanation":"Surfactant lowers surface tension. Deficiency promotes collapse and reduces compliance.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-023","conceptId":"PLX-HYA-C023","systems":["Cardiology","Pulmonary"],"topic":"LV failure causes hydrostatic pulmonary edema","tier":1,"prompt":"Put the four selected steps in order.","context":"Left ventricular systolic pump failure with pulmonary venous congestion. Order the selected backward-pressure pathway.","steps":[{"id":"s1","text":"Left ventricular pump function falls","why":"Impaired LV ejection can raise pressure upstream in the left heart."},{"id":"s2","text":"Left atrial pressure rises","why":"Higher LV filling pressure is transmitted to the left atrium."},{"id":"s3","text":"Pulmonary capillary pressure rises","why":"Pulmonary venous and capillary hydrostatic pressure increase."},{"id":"s4","text":"Pulmonary fluid filtration increases","why":"Hydrostatic pressure favors fluid movement into lung interstitium and alveoli."}],"explanation":"Left-sided failure raises pulmonary venous pressure. Increased capillary hydrostatic pressure promotes edema.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-024","conceptId":"PLX-HYA-C024","systems":["Cardiology","Physiology"],"topic":"Baroreflex response to rising pressure","tier":2,"prompt":"Put the four selected steps in order.","context":"Immediate intact reflex after a rise in systemic arterial pressure; focus on the cardiac vagal branch.","steps":[{"id":"s1","text":"Systemic arterial pressure rises","why":"A pressure increase stretches the carotid sinus wall."},{"id":"s2","text":"Carotid baroreceptor firing rises","why":"Stretch increases afferent signaling through the glossopharyngeal nerve."},{"id":"s3","text":"Cardiac vagal outflow rises","why":"Medullary integration increases parasympathetic signaling to the heart."},{"id":"s4","text":"Sinoatrial firing rate falls","why":"Vagal input slows sinoatrial pacemaker firing and heart rate."}],"explanation":"Higher arterial stretch increases baroreceptor afferent firing, which increases cardiac vagal influence and slows the heart.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-025","conceptId":"PLX-HYA-C025","systems":["Cardiology","Pharmacology"],"topic":"Nitrate preload reduction","tier":1,"prompt":"Put the four selected steps in order.","context":"Selected predominant venous effect of a nitrate at an antianginal dose; intermediate NO-cGMP signaling is omitted.","steps":[{"id":"s1","text":"Venous smooth muscle relaxes","why":"Nitrates relax venous smooth muscle and increase venous capacitance."},{"id":"s2","text":"Peripheral venous pooling increases","why":"More blood remains in the peripheral venous reservoir."},{"id":"s3","text":"Venous return to the heart falls","why":"Less blood returns centrally during the selected response."},{"id":"s4","text":"Left ventricular preload falls","why":"Reduced filling lowers LV end-diastolic preload."}],"explanation":"Nitrate-mediated venodilation shifts blood into the peripheral venous reservoir, reducing cardiac filling and preload.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-026","conceptId":"PLX-HYA-C026","systems":["Hematology"],"topic":"DIC and D-dimer formation","tier":2,"prompt":"Put the four selected steps in order.","context":"Order selected events leading to increased D-dimer in DIC. Fibrin cross-linking is implicit before plasmin breakdown.","steps":[{"id":"s1","text":"Systemic coagulation is activated","why":"DIC activates coagulation across the circulation."},{"id":"s2","text":"Fibrin deposition increases","why":"More thrombin activity generates fibrin that is subsequently cross-linked."},{"id":"s3","text":"Plasmin degrades cross-linked fibrin","why":"Plasmin-mediated fibrinolysis cleaves cross-linked fibrin."},{"id":"s4","text":"D-dimer concentration rises","why":"D-dimer fragments enter circulation as a result of that breakdown."}],"explanation":"DIC drives both fibrin formation and breakdown. D-dimer reflects degradation of cross-linked fibrin.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-027","conceptId":"PLX-HYA-C027","systems":["Hematology","Biochemistry"],"topic":"G6PD oxidative hemolysis and bilirubin","tier":1,"prompt":"Put the four selected steps in order.","context":"G6PD deficiency with sufficient oxidant exposure to trigger hemolysis. Order selected consequences.","steps":[{"id":"s1","text":"Oxidant drug exposure occurs","why":"An oxidant stressor such as dapsone challenges red cell antioxidant defenses."},{"id":"s2","text":"Red cell oxidative injury develops","why":"Limited NADPH-dependent defense permits oxidative injury."},{"id":"s3","text":"Hemolysis increases","why":"Damaged red cells are destroyed more rapidly."},{"id":"s4","text":"Indirect bilirubin production rises","why":"Increased heme breakdown raises unconjugated bilirubin production."}],"explanation":"Oxidative injury causes red cell destruction. Greater heme turnover raises the indirect bilirubin load.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-028","conceptId":"PLX-HYA-C028","systems":["Biochemistry"],"topic":"Selected gluconeogenic intermediates","tier":2,"prompt":"Put the four selected steps in order.","context":"Order selected metabolites along gluconeogenesis from pyruvate to glucose; intervening metabolites are omitted.","steps":[{"id":"s1","text":"Pyruvate","why":"Pyruvate can serve as a gluconeogenic starting substrate."},{"id":"s2","text":"Oxaloacetate","why":"Pyruvate carboxylase converts pyruvate to oxaloacetate."},{"id":"s3","text":"Phosphoenolpyruvate","why":"PEP carboxykinase forms phosphoenolpyruvate from oxaloacetate."},{"id":"s4","text":"Glucose","why":"Several subsequent reactions produce glucose."}],"explanation":"Pyruvate carboxylase acts before PEP carboxykinase. The selected intermediates therefore proceed through oxaloacetate and PEP toward glucose.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-029","conceptId":"PLX-HYA-C029","systems":["Pharmacology","Biochemistry"],"topic":"Histamine H2 signaling","tier":1,"prompt":"Put the four selected steps in order.","context":"Normal gastric parietal cell H2 receptor activation. Order selected signaling steps; cimetidine would oppose this pathway.","steps":[{"id":"s1","text":"Histamine activates the H2 receptor","why":"Histamine activates the parietal cell H2 receptor."},{"id":"s2","text":"Gs stimulates adenylyl cyclase","why":"H2 receptor signaling couples to stimulatory G protein activity."},{"id":"s3","text":"Intracellular cAMP rises","why":"Adenylyl cyclase generates the second messenger cAMP."},{"id":"s4","text":"Parietal acid secretion increases","why":"Downstream signaling increases gastric acid secretion."}],"explanation":"H2 receptor activation increases cAMP through Gs and adenylyl cyclase. H2 antagonists reduce this stimulation of acid secretion.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-SEQ-030","conceptId":"PLX-HYA-C030","systems":["Reproductive","Biochemistry"],"topic":"Oxytocin Gq signaling","tier":2,"prompt":"Put the four selected steps in order.","context":"Order the selected Gq pathway after oxytocin receptor activation in uterine smooth muscle.","steps":[{"id":"s1","text":"Oxytocin activates its receptor","why":"Oxytocin binds its G-protein-coupled receptor."},{"id":"s2","text":"Gq activates phospholipase C","why":"Activated Gq stimulates phospholipase C."},{"id":"s3","text":"PIP2 yields IP3 and DAG","why":"Phospholipase C cleaves PIP2 into IP3 and DAG."},{"id":"s4","text":"IP3 releases calcium from the ER","why":"IP3 acts on ER receptors to release stored calcium."}],"explanation":"Oxytocin uses a Gq-PLC pathway. IP3 releases intracellular calcium, while DAG supports protein kinase C signaling.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}}],"missingStep":[{"contentId":"PLX-HYA-MIS-001","conceptId":"PLX-HYA-C001","systems":["Renal","Endocrine"],"topic":"RAAS cascade","tier":1,"prompt":"Tap the step that completes this chain.","context":"Order selected stages of the renin-angiotensin-aldosterone cascade. Intermediate receptor signals are omitted.","chain":["Angiotensinogen","Angiotensin I","Angiotensin II","Aldosterone release"],"missingIndex":1,"correctId":"A","choices":[{"id":"A","text":"Angiotensin I","correct":true,"why":"Renin cleaves angiotensinogen to angiotensin I."},{"id":"B","text":"Bradykinin","correct":false,"why":"Bradykinin is degraded by ACE but is not the renin-generated angiotensin precursor."},{"id":"C","text":"Cortisol","correct":false,"why":"Cortisol is an adrenal glucocorticoid, not an angiotensin precursor."},{"id":"D","text":"Atrial natriuretic peptide","correct":false,"why":"ANP is an atrial volume signal, not the product of renin cleavage."}],"explanation":"Renin acts first on angiotensinogen. ACE then forms angiotensin II, which stimulates aldosterone release.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-002","conceptId":"PLX-HYA-C002","systems":["Renal","Endocrine"],"topic":"Aldosterone sodium-retaining mechanism","tier":1,"prompt":"Tap the step that completes this chain.","context":"Order the selected direct mineralocorticoid pathway with adequate sodium and water availability.","chain":["Mineralocorticoid receptor is activated","Distal sodium transport capacity rises","Distal sodium reabsorption rises","Extracellular volume expands"],"missingIndex":2,"correctId":"B","choices":[{"id":"A","text":"Proximal phosphate transport is blocked","correct":false,"why":"PTH-mediated phosphate handling is a different pathway."},{"id":"B","text":"Distal sodium reabsorption rises","correct":true,"why":"More sodium moves from tubular fluid back into the body."},{"id":"C","text":"Distal sodium secretion rises","correct":false,"why":"Sodium retention requires reabsorption rather than increased sodium secretion."},{"id":"D","text":"Distal potassium reabsorption rises","correct":false,"why":"The classic net potassium effect is enhanced secretion, not potassium reabsorption."}],"explanation":"Mineralocorticoid signaling increases distal sodium reabsorption. Associated water retention supports volume expansion.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-003","conceptId":"PLX-HYA-C003","systems":["Endocrine"],"topic":"ACTH-driven adrenal pigmentation","tier":2,"prompt":"Tap the step that completes this chain.","context":"Primary adrenal cortisol deficiency with a functioning pituitary. Order the selected pigmentation pathway.","chain":["Adrenal cortisol output falls","Pituitary ACTH secretion rises","Melanocortin signaling increases","Skin hyperpigmentation develops"],"missingIndex":1,"correctId":"C","choices":[{"id":"A","text":"Pituitary dopamine secretion rises","correct":false,"why":"Dopamine primarily regulates prolactin and does not explain this pigmentation chain."},{"id":"B","text":"Aldosterone directly darkens skin","correct":false,"why":"Aldosterone is not the melanocortin signal responsible for pigmentation."},{"id":"C","text":"Pituitary ACTH secretion rises","correct":true,"why":"Reduced cortisol feedback increases ACTH production."},{"id":"D","text":"Pituitary ACTH secretion falls","correct":false,"why":"A functioning pituitary responds to low cortisol by raising ACTH."}],"explanation":"Loss of cortisol feedback raises ACTH. Increased melanocortin activity explains why pigmentation suggests primary rather than isolated central adrenal failure.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-004","conceptId":"PLX-HYA-C004","systems":["Endocrine","Renal"],"topic":"ADH collecting duct action","tier":1,"prompt":"Tap the step that completes this chain.","context":"Normal V2 responsiveness, intact medullary gradient and adequate collecting duct flow. Order the selected ADH pathway.","chain":["ADH activates collecting duct V2 receptors","Apical aquaporin-2 insertion increases","Water permeability rises","Urine becomes more concentrated"],"missingIndex":2,"correctId":"D","choices":[{"id":"A","text":"Renal phosphate secretion is activated","correct":false,"why":"Phosphate handling does not mediate this ADH effect."},{"id":"B","text":"Collecting duct water permeability falls","correct":false,"why":"Aquaporin insertion increases rather than decreases water permeability."},{"id":"C","text":"Proximal glucose transport is blocked","correct":false,"why":"Proximal glucose transport is not the concentrating mechanism of ADH."},{"id":"D","text":"Water permeability rises","correct":true,"why":"Additional channels allow more water to leave the tubular lumen."}],"explanation":"ADH increases collecting duct water permeability through aquaporin-2. With an intact gradient, water is reabsorbed and the urine concentrates.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-005","conceptId":"PLX-HYA-C005","systems":["Endocrine"],"topic":"Destructive thyroiditis feedback","tier":1,"prompt":"Tap the step that completes this chain.","context":"Thyrotoxic phase of destructive thyroiditis. Order the selected causal steps.","chain":["Thyroid follicles are injured","Stored thyroid hormone is released","Circulating free thyroid hormone rises","Pituitary TSH secretion falls"],"missingIndex":1,"correctId":"A","choices":[{"id":"A","text":"Stored thyroid hormone is released","correct":true,"why":"Preformed hormone leaks into the circulation."},{"id":"B","text":"Pituitary TSH secretion rises first","correct":false,"why":"High TSH is not the initiating event in this destructive pathway."},{"id":"C","text":"New hormone synthesis alone accelerates","correct":false,"why":"Destructive thyrotoxicosis comes mainly from release of preformed hormone."},{"id":"D","text":"TSH-receptor antibodies drive synthesis","correct":false,"why":"Receptor-stimulating antibodies describe Graves disease rather than destructive release."}],"explanation":"Inflammation releases stored hormone. Negative feedback then lowers TSH, while radioiodine uptake remains low during the thyrotoxic phase.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-006","conceptId":"PLX-HYA-C006","systems":["Endocrine"],"topic":"TBG feedback adaptation","tier":2,"prompt":"Tap the step that completes this chain.","context":"Conceptual response to an isolated abrupt rise in TBG, with an intact thyroid axis; order the transient feedback steps.","chain":["Thyroid-binding globulin rises","Free T4 transiently falls","Pituitary TSH transiently rises","Thyroid hormone synthesis increases"],"missingIndex":2,"correctId":"B","choices":[{"id":"A","text":"Thyroid hormone synthesis stops","correct":false,"why":"Increased binding does not require complete cessation of synthesis."},{"id":"B","text":"Pituitary TSH transiently rises","correct":true,"why":"Reduced free-hormone feedback permits a temporary TSH increase."},{"id":"C","text":"Pituitary TSH transiently falls","correct":false,"why":"A temporary free T4 decrease reduces feedback and tends to raise TSH."},{"id":"D","text":"The pituitary cannot sense free hormone","correct":false,"why":"An intact pituitary responds to the free-hormone feedback change."}],"explanation":"More binding initially lowers free T4. Feedback increases hormone production, restoring free hormone while total T4 remains higher.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-007","conceptId":"PLX-HYA-C007","systems":["Endocrine","Musculoskeletal"],"topic":"PTH activates bone resorption indirectly","tier":2,"prompt":"Tap the step that completes this chain.","context":"Selected pathway during sustained PTH signaling; intermediate osteoclast differentiation signals are omitted.","chain":["PTH stimulates osteoblast-lineage cells","RANKL signaling increases","Osteoclast activation increases","Bone resorption increases"],"missingIndex":1,"correctId":"C","choices":[{"id":"A","text":"Osteoblast RANKL signaling falls","correct":false,"why":"Reduced RANKL would not explain increased osteoclast activation."},{"id":"B","text":"Calcitonin activates osteoclasts","correct":false,"why":"Calcitonin inhibits rather than activates osteoclast-mediated resorption."},{"id":"C","text":"RANKL signaling increases","correct":true,"why":"These cells increase the osteoclast-promoting RANKL signal."},{"id":"D","text":"PTH directly activates osteoclast PTH1R","correct":false,"why":"The classic PTH effect on osteoclasts is indirect through osteoblast-lineage signaling."}],"explanation":"PTH communicates through osteoblast-lineage cells to increase RANKL-mediated osteoclast activity.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-008","conceptId":"PLX-HYA-C008","systems":["Endocrine","Biochemistry"],"topic":"Vitamin D activation route","tier":1,"prompt":"Tap the step that completes this chain.","context":"Order selected stages of cutaneous vitamin D3 formation and activation. Previtamin and transport steps are omitted.","chain":["UVB acts on skin 7-dehydrocholesterol","Skin forms cholecalciferol","Liver forms 25-hydroxyvitamin D","Kidney forms 1,25-dihydroxyvitamin D"],"missingIndex":2,"correctId":"D","choices":[{"id":"A","text":"Liver directly forms calcitriol","correct":false,"why":"The principal regulated 1-alpha activation step occurs in the kidney."},{"id":"B","text":"Skin forms 24,25-dihydroxyvitamin D","correct":false,"why":"Skin vitamin D3 formation is not the 24,25-hydroxylation pathway."},{"id":"C","text":"Kidney performs initial 25-hydroxylation","correct":false,"why":"The classic main 25-hydroxylation step occurs in the liver."},{"id":"D","text":"Liver forms 25-hydroxyvitamin D","correct":true,"why":"Hepatic hydroxylation forms calcidiol, the major circulating 25-hydroxy form."}],"explanation":"The selected route is skin vitamin D3 formation, hepatic 25-hydroxylation, then renal 1-alpha-hydroxylation.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-009","conceptId":"PLX-HYA-C009","systems":["Renal","Endocrine"],"topic":"CKD calcitriol-calcium-PTH pathway","tier":2,"prompt":"Tap the step that completes this chain.","context":"Selected vitamin D pathway in advanced untreated CKD; phosphate retention is an additional parallel contributor.","chain":["Functioning renal tissue declines","Renal calcitriol production falls","Intestinal calcium absorption falls","Secondary PTH secretion increases"],"missingIndex":1,"correctId":"A","choices":[{"id":"A","text":"Renal calcitriol production falls","correct":true,"why":"Renal activation of vitamin D is impaired."},{"id":"B","text":"Renal PTH synthesis stops","correct":false,"why":"PTH is produced by the parathyroids, not the kidney."},{"id":"C","text":"Macrophage calcitriol production dominates","correct":false,"why":"Granuloma macrophage activation describes a different mechanism."},{"id":"D","text":"Renal calcitriol production rises","correct":false,"why":"In this selected advanced CKD pathway, renal activation falls."}],"explanation":"Reduced renal calcitriol production contributes to impaired calcium absorption and secondary PTH elevation.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-010","conceptId":"PLX-HYA-C010","systems":["Endocrine","Pulmonary"],"topic":"Sarcoid calcitriol hypercalcemia","tier":2,"prompt":"Tap the step that completes this chain.","context":"Sarcoidosis with calcitriol-mediated hypercalcemia. Order the selected pathway; serum calcium elevation is implicit before PTH suppression.","chain":["Granuloma macrophage 1-alpha activity rises","Calcitriol production rises","Intestinal calcium absorption rises","Endogenous PTH secretion falls"],"missingIndex":2,"correctId":"B","choices":[{"id":"A","text":"Calcitriol blocks intestinal calcium uptake","correct":false,"why":"Calcitriol supports intestinal calcium uptake rather than blocking it."},{"id":"B","text":"Intestinal calcium absorption rises","correct":true,"why":"Calcitriol promotes intestinal calcium uptake."},{"id":"C","text":"Intestinal calcium absorption falls","correct":false,"why":"More calcitriol promotes rather than reduces calcium absorption."},{"id":"D","text":"Parathyroid PTH secretion rises","correct":false,"why":"Calcium-driven feedback suppresses endogenous PTH in this setting."}],"explanation":"Extrarenal calcitriol generation raises intestinal calcium absorption. The resulting hypercalcemia suppresses endogenous PTH.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-011","conceptId":"PLX-HYA-C011","systems":["Reproductive","Endocrine"],"topic":"Ovarian failure feedback","tier":1,"prompt":"Tap the step that completes this chain.","context":"Established primary ovarian failure. Order the selected loss-of-feedback pathway.","chain":["Ovarian follicular function declines","Estrogen and inhibin secretion fall","Pituitary negative feedback weakens","FSH secretion increases"],"missingIndex":1,"correctId":"C","choices":[{"id":"A","text":"Pituitary FSH synthesis is destroyed","correct":false,"why":"Pituitary destruction would cause central, not primary ovarian, hypogonadism."},{"id":"B","text":"Hypothalamic GnRH is shut off","correct":false,"why":"A functioning central axis increases its drive rather than shutting off."},{"id":"C","text":"Estrogen and inhibin secretion fall","correct":true,"why":"The ovaries supply less estrogen and inhibin."},{"id":"D","text":"Estrogen and inhibin secretion rise","correct":false,"why":"In primary ovarian failure, ovarian feedback hormone output declines."}],"explanation":"Reduced ovarian estrogen and inhibin remove negative feedback, allowing gonadotropins, especially FSH, to rise.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-012","conceptId":"PLX-HYA-C012","systems":["Reproductive","Endocrine"],"topic":"Male LH-testosterone signaling","tier":1,"prompt":"Tap the step that completes this chain.","context":"Normal male hypothalamic-pituitary-gonadal axis. Order the selected stimulatory signals.","chain":["Hypothalamic GnRH pulse occurs","Pituitary LH is released","Testicular Leydig cells are stimulated","Testosterone synthesis increases"],"missingIndex":2,"correctId":"D","choices":[{"id":"A","text":"Ovarian granulosa cells are stimulated","correct":false,"why":"Ovarian granulosa cells are not the male testicular target."},{"id":"B","text":"FSH selectively activates Sertoli cells","correct":false,"why":"Sertoli signaling is important for testicular function but is not the selected LH-to-testosterone step."},{"id":"C","text":"Adrenal glomerulosa cells are stimulated","correct":false,"why":"Adrenal glomerulosa cells chiefly regulate aldosterone production."},{"id":"D","text":"Testicular Leydig cells are stimulated","correct":true,"why":"LH activates its receptor on Leydig cells."}],"explanation":"GnRH drives pituitary LH release. LH stimulates Leydig cells to produce testosterone.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-013","conceptId":"PLX-HYA-C013","systems":["Endocrine","Pharmacology"],"topic":"D2 blockade and reproductive suppression","tier":2,"prompt":"Tap the step that completes this chain.","context":"Sustained D2 antagonist exposure with clinically significant hyperprolactinemia. Order the selected pathway.","chain":["Pituitary D2 receptors are blocked","Prolactin secretion rises","GnRH pulsatility declines","Gonadotropin drive declines"],"missingIndex":1,"correctId":"A","choices":[{"id":"A","text":"Prolactin secretion rises","correct":true,"why":"Disinhibited lactotrophs release more prolactin."},{"id":"B","text":"Prolactin secretion falls","correct":false,"why":"D2 antagonism generally increases rather than suppresses prolactin."},{"id":"C","text":"Pituitary lactotrophs are destroyed","correct":false,"why":"D2 blockade changes signaling; it does not require lactotroph destruction."},{"id":"D","text":"Dopamine inhibition becomes stronger","correct":false,"why":"Receptor blockade weakens the dopamine signal."}],"explanation":"Dopamine normally suppresses prolactin. Removing that inhibition can raise prolactin enough to suppress the gonadal axis.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-014","conceptId":"PLX-HYA-C014","systems":["Reproductive","Endocrine"],"topic":"Exogenous androgen feedback","tier":2,"prompt":"Tap the step that completes this chain.","context":"Sustained exogenous androgen exposure. Order a selected pathway that can impair spermatogenesis.","chain":["Exogenous androgen exposure increases","Pituitary LH secretion falls","Intratesticular testosterone falls","Spermatogenesis can decline"],"missingIndex":2,"correctId":"B","choices":[{"id":"A","text":"Pituitary FSH drive rises","correct":false,"why":"Exogenous androgen suppresses rather than predictably increases gonadotropin drive."},{"id":"B","text":"Intratesticular testosterone falls","correct":true,"why":"Less Leydig stimulation reduces the high local testosterone concentration."},{"id":"C","text":"Leydig cells escape negative feedback","correct":false,"why":"The mechanism depends on feedback-induced reduction of Leydig stimulation."},{"id":"D","text":"Intratesticular testosterone rises","correct":false,"why":"Serum androgen can be high while endogenous intratesticular production falls."}],"explanation":"Exogenous androgen can raise circulating androgen while suppressing endogenous gonadotropins and local testicular testosterone.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-015","conceptId":"PLX-HYA-C015","systems":["Renal","Pharmacology"],"topic":"Loop diuretic contraction alkalosis","tier":2,"prompt":"Tap the step that completes this chain.","context":"A loop diuretic causes effective volume contraction. Order the selected sequence; changes can overlap in real time.","chain":["Loop diuretic inhibits NKCC2","Urinary sodium and water loss increases","Renin-angiotensin drive increases","Distal hydrogen secretion increases"],"missingIndex":1,"correctId":"C","choices":[{"id":"A","text":"Aldosterone receptors are blocked","correct":false,"why":"Loop diuretics inhibit NKCC2, not mineralocorticoid receptors."},{"id":"B","text":"Tubular sodium reabsorption rises first","correct":false,"why":"The initiating transporter block decreases salt reclamation at its target."},{"id":"C","text":"Urinary sodium and water loss increases","correct":true,"why":"More sodium and water are excreted."},{"id":"D","text":"Effective circulating volume expands","correct":false,"why":"This chain specifies effective volume contraction from diuresis."}],"explanation":"Loop-induced salt and water loss can activate RAAS, increasing distal hydrogen loss and sustaining metabolic alkalosis.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-016","conceptId":"PLX-HYA-C016","systems":["Renal","Pharmacology"],"topic":"Acetazolamide bicarbonaturia","tier":1,"prompt":"Tap the step that completes this chain.","context":"Early effect of acetazolamide with preserved kidney function. Order the selected urinary pathway.","chain":["Renal carbonic anhydrase is inhibited","Proximal bicarbonate reclamation falls","Urinary bicarbonate excretion rises","Urine pH rises"],"missingIndex":2,"correctId":"D","choices":[{"id":"A","text":"Urinary hydrogen retention is the cause","correct":false,"why":"The selected urine alkalinization is caused by bicarbonate loss into urine."},{"id":"B","text":"Urinary bicarbonate excretion falls","correct":false,"why":"Inhibited proximal reclamation initially increases bicarbonaturia."},{"id":"C","text":"All filtered bicarbonate is retained","correct":false,"why":"Complete retention conflicts with the transporter effect."},{"id":"D","text":"Urinary bicarbonate excretion rises","correct":true,"why":"More bicarbonate remains in the tubular fluid and is excreted."}],"explanation":"Acetazolamide causes bicarbonate loss into urine. Urine pH rises while plasma bicarbonate falls.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-017","conceptId":"PLX-HYA-C017","systems":["Endocrine","Biochemistry"],"topic":"DKA ketone-acid pathway","tier":1,"prompt":"Tap the step that completes this chain.","context":"Severe insulin deficiency with unchecked ketogenesis. Order the selected sequence; glucagon drive is implicit.","chain":["Insulin action falls","Adipose lipolysis increases","Hepatic ketone production increases","Plasma bicarbonate falls"],"missingIndex":1,"correctId":"A","choices":[{"id":"A","text":"Adipose lipolysis increases","correct":true,"why":"Fatty acids are released from adipose stores."},{"id":"B","text":"Hepatic fatty acid supply disappears","correct":false,"why":"Mobilized adipose fat increases hepatic fatty acid supply."},{"id":"C","text":"Insulin-mediated GLUT4 uptake rises","correct":false,"why":"GLUT4-mediated glucose uptake is not increased by insulin deficiency."},{"id":"D","text":"Adipose lipolysis is suppressed","correct":false,"why":"Insulin deficiency removes inhibition of lipolysis."}],"explanation":"Low insulin and counterregulatory signaling increase lipolysis and ketogenesis. Ketoacid buffering lowers bicarbonate.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-018","conceptId":"PLX-HYA-C018","systems":["Endocrine","Renal"],"topic":"Hyperglycemic osmotic diuresis","tier":1,"prompt":"Tap the step that completes this chain.","context":"Hyperglycemia exceeds renal glucose reabsorptive capacity. Order the selected tubular water-loss pathway.","chain":["Plasma glucose rises markedly","Filtered glucose exceeds reabsorption","Glucose retains water in tubular fluid","Osmotic diuresis develops"],"missingIndex":2,"correctId":"B","choices":[{"id":"A","text":"Urinary glucose forces water into blood","correct":false,"why":"The relevant glucose holds water in urine rather than forcing it back into blood."},{"id":"B","text":"Glucose retains water in tubular fluid","correct":true,"why":"Unreabsorbed glucose acts as an osmole within tubular fluid."},{"id":"C","text":"Glucose removes all tubular osmoles","correct":false,"why":"Glucose adds a poorly reclaimed osmotic load in this setting."},{"id":"D","text":"Insulin inserts collecting duct aquaporins","correct":false,"why":"The osmotic diuresis mechanism is not insulin-mediated aquaporin insertion."}],"explanation":"Glucosuria retains water in the tubular lumen, producing osmotic diuresis and contributing to volume and electrolyte losses.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-019","conceptId":"PLX-HYA-C019","systems":["Endocrine","Nutrition"],"topic":"Refeeding hypophosphatemia","tier":1,"prompt":"Tap the step that completes this chain.","context":"A person with depleted stores receives substantial carbohydrate after prolonged undernutrition. Order the selected pathway.","chain":["Carbohydrate feeding resumes","Insulin secretion increases","Cellular phosphate uptake and use rise","Serum phosphate falls"],"missingIndex":1,"correctId":"C","choices":[{"id":"A","text":"Insulin secretion decreases","correct":false,"why":"Carbohydrate refeeding normally raises insulin."},{"id":"B","text":"Renal phosphate release replaces insulin","correct":false,"why":"Renal handling does not replace the insulin-mediated cellular shift in this selected chain."},{"id":"C","text":"Insulin secretion increases","correct":true,"why":"The pancreas releases insulin in response to the carbohydrate load."},{"id":"D","text":"Glucagon becomes the dominant fed signal","correct":false,"why":"The fed anabolic transition is driven chiefly by rising insulin rather than dominant glucagon."}],"explanation":"Carbohydrate-driven insulin release promotes cellular uptake and use of phosphate. Depleted stores make a dangerous serum phosphate fall more likely.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-020","conceptId":"PLX-HYA-C020","systems":["Pulmonary","Neurology"],"topic":"Hyperventilation and cerebral blood flow","tier":2,"prompt":"Tap the step that completes this chain.","context":"Acute hyperventilation with stable oxygen delivery and no overriding cerebrovascular pathology.","chain":["Alveolar ventilation rises","Arterial PaCO2 falls","Cerebral arterioles constrict","Cerebral blood flow falls"],"missingIndex":2,"correctId":"D","choices":[{"id":"A","text":"Cerebral vascular resistance falls","correct":false,"why":"Vasoconstriction increases rather than decreases vascular resistance."},{"id":"B","text":"Hypocapnia increases cerebral flow","correct":false,"why":"The usual hypocapnic response is lower cerebral blood flow."},{"id":"C","text":"Cerebral arterioles dilate","correct":false,"why":"Acute hypocapnia characteristically causes cerebral vasoconstriction."},{"id":"D","text":"Cerebral arterioles constrict","correct":true,"why":"Hypocapnia produces cerebral vasoconstriction."}],"explanation":"Hypocapnia constricts cerebral vessels and can contribute to lightheadedness during hyperventilation.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-021","conceptId":"PLX-HYA-C021","systems":["Pulmonary","Genetics"],"topic":"Alpha-1-antitrypsin emphysema pathway","tier":1,"prompt":"Tap the step that completes this chain.","context":"Selected pulmonary mechanism of alpha-1-antitrypsin deficiency; intermediate inflammatory events are omitted.","chain":["Alpha-1-antitrypsin protection falls","Elastase activity becomes unopposed","Alveolar walls are damaged","Emphysematous air trapping develops"],"missingIndex":1,"correctId":"A","choices":[{"id":"A","text":"Elastase activity becomes unopposed","correct":true,"why":"Insufficient inhibition permits excess elastase-mediated damage."},{"id":"B","text":"Surfactant production is the primary block","correct":false,"why":"Surfactant deficiency is not the primary alpha-1-antitrypsin mechanism."},{"id":"C","text":"Collagen deposition stiffens alveoli","correct":false,"why":"Fibrotic stiffening is a different mechanical process."},{"id":"D","text":"Elastase activity is fully suppressed","correct":false,"why":"Loss of an elastase inhibitor permits rather than suppresses elastase action."}],"explanation":"Alpha-1-antitrypsin inhibits elastase. Reduced protection allows protease-mediated tissue destruction and emphysema.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-022","conceptId":"PLX-HYA-C022","systems":["Pulmonary"],"topic":"Surfactant deficiency mechanics","tier":1,"prompt":"Tap the step that completes this chain.","context":"Prematurity-related surfactant deficiency. Order selected mechanical consequences.","chain":["Surfactant availability falls","Alveolar surface tension rises","Alveolar collapse tendency rises","Lung compliance falls"],"missingIndex":2,"correctId":"B","choices":[{"id":"A","text":"Collapsing pressure falls","correct":false,"why":"Higher surface tension increases the collapsing pressure tendency."},{"id":"B","text":"Alveolar collapse tendency rises","correct":true,"why":"Higher surface tension makes alveoli less stable."},{"id":"C","text":"Alveolar collapse tendency falls","correct":false,"why":"A surfactant-deficient alveolus is more prone to collapse."},{"id":"D","text":"Alveolar stability increases","correct":false,"why":"Loss of surfactant reduces stability."}],"explanation":"Surfactant lowers surface tension. Deficiency promotes collapse and reduces compliance.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-023","conceptId":"PLX-HYA-C023","systems":["Cardiology","Pulmonary"],"topic":"LV failure causes hydrostatic pulmonary edema","tier":1,"prompt":"Tap the step that completes this chain.","context":"Left ventricular systolic pump failure with pulmonary venous congestion. Order the selected backward-pressure pathway.","chain":["Left ventricular pump function falls","Left atrial pressure rises","Pulmonary capillary pressure rises","Pulmonary fluid filtration increases"],"missingIndex":1,"correctId":"C","choices":[{"id":"A","text":"Right atrial pressure alone determines edema","correct":false,"why":"Isolated right atrial pressure does not explain the selected left-sided hydrostatic pathway."},{"id":"B","text":"Pulmonary venous outflow is enhanced","correct":false,"why":"Improved outflow would relieve rather than produce this congestion."},{"id":"C","text":"Left atrial pressure rises","correct":true,"why":"Higher LV filling pressure is transmitted to the left atrium."},{"id":"D","text":"Left atrial pressure falls","correct":false,"why":"The selected congestion pathway raises rather than lowers left atrial pressure."}],"explanation":"Left-sided failure raises pulmonary venous pressure. Increased capillary hydrostatic pressure promotes edema.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-024","conceptId":"PLX-HYA-C024","systems":["Cardiology","Physiology"],"topic":"Baroreflex response to rising pressure","tier":2,"prompt":"Tap the step that completes this chain.","context":"Immediate intact reflex after a rise in systemic arterial pressure; focus on the cardiac vagal branch.","chain":["Systemic arterial pressure rises","Carotid baroreceptor firing rises","Cardiac vagal outflow rises","Sinoatrial firing rate falls"],"missingIndex":2,"correctId":"D","choices":[{"id":"A","text":"Cardiac sympathetic outflow rises","correct":false,"why":"In this reflex, cardiac sympathetic drive is reduced."},{"id":"B","text":"Cardiac vagal outflow falls","correct":false,"why":"The cardiac vagal response to increased baroreceptor firing is increased outflow."},{"id":"C","text":"Aldosterone is the immediate vagal signal","correct":false,"why":"Aldosterone is not the neural efferent signal slowing the sinoatrial node."},{"id":"D","text":"Cardiac vagal outflow rises","correct":true,"why":"Medullary integration increases parasympathetic signaling to the heart."}],"explanation":"Higher arterial stretch increases baroreceptor afferent firing, which increases cardiac vagal influence and slows the heart.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-025","conceptId":"PLX-HYA-C025","systems":["Cardiology","Pharmacology"],"topic":"Nitrate preload reduction","tier":1,"prompt":"Tap the step that completes this chain.","context":"Selected predominant venous effect of a nitrate at an antianginal dose; intermediate NO-cGMP signaling is omitted.","chain":["Venous smooth muscle relaxes","Peripheral venous pooling increases","Venous return to the heart falls","Left ventricular preload falls"],"missingIndex":1,"correctId":"A","choices":[{"id":"A","text":"Peripheral venous pooling increases","correct":true,"why":"More blood remains in the peripheral venous reservoir."},{"id":"B","text":"Peripheral venous pooling decreases","correct":false,"why":"Venodilation increases peripheral capacitance and pooling."},{"id":"C","text":"Venous smooth muscle constricts","correct":false,"why":"The nitrate mechanism begins with relaxation, not constriction."},{"id":"D","text":"Venous blood shifts centrally","correct":false,"why":"A central volume shift would tend to increase rather than reduce preload."}],"explanation":"Nitrate-mediated venodilation shifts blood into the peripheral venous reservoir, reducing cardiac filling and preload.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-026","conceptId":"PLX-HYA-C026","systems":["Hematology"],"topic":"DIC and D-dimer formation","tier":2,"prompt":"Tap the step that completes this chain.","context":"Order selected events leading to increased D-dimer in DIC. Fibrin cross-linking is implicit before plasmin breakdown.","chain":["Systemic coagulation is activated","Fibrin deposition increases","Plasmin degrades cross-linked fibrin","D-dimer concentration rises"],"missingIndex":2,"correctId":"B","choices":[{"id":"A","text":"Fibrinogen alone yields D-dimer","correct":false,"why":"D-dimer specifically reflects breakdown of cross-linked fibrin, not fibrinogen alone."},{"id":"B","text":"Plasmin degrades cross-linked fibrin","correct":true,"why":"Plasmin-mediated fibrinolysis cleaves cross-linked fibrin."},{"id":"C","text":"Plasmin prevents all fibrin degradation","correct":false,"why":"Plasmin is the fibrinolytic enzyme that breaks fibrin down."},{"id":"D","text":"Thrombin directly releases D-dimer","correct":false,"why":"Thrombin generates fibrin; plasmin degradation of cross-linked fibrin produces D-dimer."}],"explanation":"DIC drives both fibrin formation and breakdown. D-dimer reflects degradation of cross-linked fibrin.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-027","conceptId":"PLX-HYA-C027","systems":["Hematology","Biochemistry"],"topic":"G6PD oxidative hemolysis and bilirubin","tier":1,"prompt":"Tap the step that completes this chain.","context":"G6PD deficiency with sufficient oxidant exposure to trigger hemolysis. Order selected consequences.","chain":["Oxidant drug exposure occurs","Red cell oxidative injury develops","Hemolysis increases","Indirect bilirubin production rises"],"missingIndex":1,"correctId":"C","choices":[{"id":"A","text":"Bilirubin conjugation is the initial defect","correct":false,"why":"The selected mechanism increases bilirubin production rather than initially impairing conjugation."},{"id":"B","text":"Common bile duct obstruction develops","correct":false,"why":"Bile duct obstruction is not the causal pathway of G6PD-related hemolysis."},{"id":"C","text":"Red cell oxidative injury develops","correct":true,"why":"Limited NADPH-dependent defense permits oxidative injury."},{"id":"D","text":"Red cell oxidative protection improves","correct":false,"why":"G6PD deficiency limits protection from the oxidant challenge."}],"explanation":"Oxidative injury causes red cell destruction. Greater heme turnover raises the indirect bilirubin load.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-028","conceptId":"PLX-HYA-C028","systems":["Biochemistry"],"topic":"Selected gluconeogenic intermediates","tier":2,"prompt":"Tap the step that completes this chain.","context":"Order selected metabolites along gluconeogenesis from pyruvate to glucose; intervening metabolites are omitted.","chain":["Pyruvate","Oxaloacetate","Phosphoenolpyruvate","Glucose"],"missingIndex":2,"correctId":"D","choices":[{"id":"A","text":"Glycogen","correct":false,"why":"Glycogen is a storage polymer, not this gluconeogenic intermediate."},{"id":"B","text":"Acetyl-CoA","correct":false,"why":"Acetyl-CoA is not the net gluconeogenic carbon route from oxaloacetate to glucose in humans."},{"id":"C","text":"Fructose-2,6-bisphosphate","correct":false,"why":"Fructose-2,6-bisphosphate is a regulator, not the selected obligatory carbon intermediate."},{"id":"D","text":"Phosphoenolpyruvate","correct":true,"why":"PEP carboxykinase forms phosphoenolpyruvate from oxaloacetate."}],"explanation":"Pyruvate carboxylase acts before PEP carboxykinase. The selected intermediates therefore proceed through oxaloacetate and PEP toward glucose.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-029","conceptId":"PLX-HYA-C029","systems":["Pharmacology","Biochemistry"],"topic":"Histamine H2 signaling","tier":1,"prompt":"Tap the step that completes this chain.","context":"Normal gastric parietal cell H2 receptor activation. Order selected signaling steps; cimetidine would oppose this pathway.","chain":["Histamine activates the H2 receptor","Gs stimulates adenylyl cyclase","Intracellular cAMP rises","Parietal acid secretion increases"],"missingIndex":1,"correctId":"A","choices":[{"id":"A","text":"Gs stimulates adenylyl cyclase","correct":true,"why":"H2 receptor signaling couples to stimulatory G protein activity."},{"id":"B","text":"The receptor directly acts as a kinase","correct":false,"why":"H2 is a G-protein-coupled receptor, not a receptor tyrosine kinase."},{"id":"C","text":"Gq activates phospholipase C","correct":false,"why":"The classic H2 pathway uses Gs-cAMP rather than Gq-IP3 signaling."},{"id":"D","text":"Gi inhibits adenylyl cyclase","correct":false,"why":"H2 is classically Gs coupled rather than Gi coupled."}],"explanation":"H2 receptor activation increases cAMP through Gs and adenylyl cyclase. H2 antagonists reduce this stimulation of acid secretion.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}},{"contentId":"PLX-HYA-MIS-030","conceptId":"PLX-HYA-C030","systems":["Reproductive","Biochemistry"],"topic":"Oxytocin Gq signaling","tier":2,"prompt":"Tap the step that completes this chain.","context":"Order the selected Gq pathway after oxytocin receptor activation in uterine smooth muscle.","chain":["Oxytocin activates its receptor","Gq activates phospholipase C","PIP2 yields IP3 and DAG","IP3 releases calcium from the ER"],"missingIndex":2,"correctId":"B","choices":[{"id":"A","text":"PIP2 is converted into cGMP","correct":false,"why":"PLC produces IP3 and DAG from PIP2, not cGMP."},{"id":"B","text":"PIP2 yields IP3 and DAG","correct":true,"why":"Phospholipase C cleaves PIP2 into IP3 and DAG."},{"id":"C","text":"ATP is converted into cAMP","correct":false,"why":"ATP-to-cAMP production belongs to adenylyl cyclase signaling rather than the selected PLC step."},{"id":"D","text":"PDE5 directly produces IP3","correct":false,"why":"PDE5 degrades cGMP and does not generate IP3."}],"explanation":"Oxytocin uses a Gq-PLC pathway. IP3 releases intracellular calcium, while DAG supports protein kinase C signaling.","review":{"status":"AI_REVIEWED_PASS","verdict":"PASS","humanVerified":false,"basis":"supplied AI audit"}}]}
